@import 'tailwindcss';

@custom-variant dark (&:where(.dark, .dark *));

/* ---------------------------------------------------------------------------
   Palette. Light is the default; `.dark` on <html> swaps the tokens in place so
   components stay theme-agnostic and just use `bg-surface`, `text-ink`, …
--------------------------------------------------------------------------- */
:root {
  --color-canvas: #f6f8fc;
  --color-surface: #ffffff;
  --color-surface-2: #f0f4f9;
  --color-surface-3: #e3e8ef;
  --color-elevated: #ffffff;

  --color-ink: #1f1f1f;
  --color-ink-2: #444746;
  --color-ink-3: #5e5e5e;
  --color-ink-4: #80868b;

  --color-line: #dadce0;
  --color-line-soft: #e8eaed;

  --color-accent: #0b57d0;
  --color-accent-hover: #0842a0;
  --color-on-accent: #ffffff;
  --color-accent-soft: #d3e3fd;
  --color-accent-ink: #0b57d0;

  --color-select: #c2e7ff;
  --color-row-hover: #f5f6f8;
  --color-unread: #ffffff;
  --color-read: #f2f6fc;

  --color-star: #f4b400;
  --color-important: #f2b600;
  --color-danger: #d93025;
  --color-success: #1e8e3e;

  --shadow-row: 0 1px 2px 0 rgb(60 64 67 / 0.3), 0 1px 3px 1px rgb(60 64 67 / 0.15);
  --shadow-pop: 0 1px 3px 0 rgb(60 64 67 / 0.3), 0 4px 8px 3px rgb(60 64 67 / 0.15);
  --shadow-compose: 0 8px 10px 1px rgb(0 0 0 / 0.14), 0 3px 14px 2px rgb(0 0 0 / 0.12),
    0 5px 5px -3px rgb(0 0 0 / 0.2);
}

.dark {
  --color-canvas: #131314;
  --color-surface: #1b1c1d;
  --color-surface-2: #232426;
  --color-surface-3: #2d2e30;
  --color-elevated: #1e1f20;

  --color-ink: #e3e3e3;
  --color-ink-2: #c4c7c5;
  --color-ink-3: #a8abb0;
  --color-ink-4: #8e918f;

  --color-line: #3c4043;
  --color-line-soft: #2f3032;

  --color-accent: #8ab4f8;
  --color-accent-hover: #aecbfa;
  --color-on-accent: #062e6f;
  --color-accent-soft: #274372;
  --color-accent-ink: #a8c7fa;

  --color-select: #1f3f5f;
  --color-row-hover: #26282a;
  --color-unread: #1b1c1d;
  --color-read: #1b1c1d;

  --color-star: #f4b400;
  --color-important: #f2b600;
  --color-danger: #f28b82;
  --color-success: #81c995;

  --shadow-row: 0 1px 2px 0 rgb(0 0 0 / 0.6), 0 1px 3px 1px rgb(0 0 0 / 0.3);
  --shadow-pop: 0 1px 3px 0 rgb(0 0 0 / 0.6), 0 4px 8px 3px rgb(0 0 0 / 0.3);
  --shadow-compose: 0 8px 10px 1px rgb(0 0 0 / 0.5), 0 3px 14px 2px rgb(0 0 0 / 0.4);
}

@theme inline {
  --color-canvas: var(--color-canvas);
  --color-surface: var(--color-surface);
  --color-surface-2: var(--color-surface-2);
  --color-surface-3: var(--color-surface-3);
  --color-elevated: var(--color-elevated);

  --color-ink: var(--color-ink);
  --color-ink-2: var(--color-ink-2);
  --color-ink-3: var(--color-ink-3);
  --color-ink-4: var(--color-ink-4);

  --color-line: var(--color-line);
  --color-line-soft: var(--color-line-soft);

  --color-accent: var(--color-accent);
  --color-accent-hover: var(--color-accent-hover);
  --color-on-accent: var(--color-on-accent);
  --color-accent-soft: var(--color-accent-soft);
  --color-accent-ink: var(--color-accent-ink);

  --color-select: var(--color-select);
  --color-row-hover: var(--color-row-hover);
  --color-unread: var(--color-unread);
  --color-read: var(--color-read);

  --color-star: var(--color-star);
  --color-important: var(--color-important);
  --color-danger: var(--color-danger);
  --color-success: var(--color-success);

  --shadow-row: var(--shadow-row);
  --shadow-pop: var(--shadow-pop);
  --shadow-compose: var(--shadow-compose);

  --font-sans:
    'Google Sans Text', 'Roboto', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui,
    sans-serif;

  --animate-pop-in: pop-in 0.14s cubic-bezier(0.2, 0, 0, 1);
  --animate-slide-up: slide-up 0.2s cubic-bezier(0.2, 0, 0, 1);
  --animate-fade-in: fade-in 0.15s ease-out;
  --animate-toast-in: toast-in 0.24s cubic-bezier(0.2, 0, 0, 1);
}

@keyframes pop-in {
  from {
    opacity: 0;
    transform: scale(0.96);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}
@keyframes slide-up {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(16px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@layer base {
  html,
  body,
  #root {
    height: 100%;
  }

  body {
    margin: 0;
    background: var(--color-canvas);
    color: var(--color-ink);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
    overscroll-behavior: none;
  }

  button {
    cursor: pointer;
    font: inherit;
    color: inherit;
  }

  input,
  textarea,
  select {
    font: inherit;
    color: inherit;
  }

  :focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
  }

  ::selection {
    background: var(--color-accent-soft);
    color: var(--color-ink);
  }
}

@layer utilities {
  .scrollbar-thin {
    scrollbar-width: thin;
    scrollbar-color: transparent transparent;
  }
  .scrollbar-thin:hover {
    scrollbar-color: color-mix(in srgb, var(--color-ink-4) 55%, transparent) transparent;
  }
  .scrollbar-thin::-webkit-scrollbar {
    width: 12px;
    height: 12px;
  }
  .scrollbar-thin::-webkit-scrollbar-thumb {
    background-color: transparent;
    border-radius: 8px;
    border: 3px solid transparent;
    background-clip: content-box;
  }
  .scrollbar-thin:hover::-webkit-scrollbar-thumb {
    background-color: color-mix(in srgb, var(--color-ink-4) 45%, transparent);
  }
  .scrollbar-thin::-webkit-scrollbar-thumb:hover {
    background-color: color-mix(in srgb, var(--color-ink-4) 75%, transparent);
  }

  .no-scrollbar {
    scrollbar-width: none;
  }
  .no-scrollbar::-webkit-scrollbar {
    display: none;
  }
}

/* Rich-text surface shared by the composer and rendered message bodies. */
.mail-body {
  font-size: 0.875rem;
  line-height: 1.62;
  color: var(--color-ink);
  word-break: break-word;
}
.mail-body p {
  margin: 0 0 0.85em;
}
.mail-body > *:last-child {
  margin-bottom: 0;
}
.mail-body a {
  color: var(--color-accent-ink);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.mail-body ul,
.mail-body ol {
  margin: 0 0 0.85em;
  padding-left: 1.5em;
}
.mail-body ul {
  list-style: disc;
}
.mail-body ol {
  list-style: decimal;
}
.mail-body li {
  margin-bottom: 0.3em;
}
.mail-body blockquote {
  margin: 0 0 0.85em;
  padding-left: 1em;
  border-left: 2px solid var(--color-line);
  color: var(--color-ink-2);
}
.mail-body h1,
.mail-body h2,
.mail-body h3 {
  margin: 0 0 0.55em;
  font-weight: 600;
  line-height: 1.3;
}
.mail-body h1 {
  font-size: 1.3rem;
}
.mail-body h2 {
  font-size: 1.1rem;
}
.mail-body h3 {
  font-size: 0.98rem;
}
.mail-body hr {
  border: 0;
  border-top: 1px solid var(--color-line-soft);
  margin: 1.2em 0;
}
.mail-body code {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.85em;
  background: var(--color-surface-2);
  padding: 0.12em 0.36em;
  border-radius: 4px;
}
.mail-body pre {
  background: var(--color-surface-2);
  padding: 0.75em 0.9em;
  border-radius: 8px;
  overflow-x: auto;
  margin: 0 0 0.85em;
  font-size: 0.82em;
}
.mail-body pre code {
  background: none;
  padding: 0;
}
.mail-body table {
  border-collapse: collapse;
  margin-bottom: 0.85em;
  font-size: 0.94em;
