import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type ReactNode,
  type RefObject,
} from 'react'
import { createPortal } from 'react-dom'
import { cn } from '@/lib/utils'

type Side = 'bottom' | 'top'
type Align = 'start' | 'end' | 'center'

interface PopoverProps {
  anchorRef: RefObject<HTMLElement | null>
  open: boolean
  onClose: () => void
  children: ReactNode
  side?: Side
  align?: Align
  /** Extra offset from the anchor, in px. */
  offset?: number
  className?: string
  matchWidth?: boolean
  /** Move keyboard focus into the panel when it opens. */
  autoFocus?: boolean
  role?: 'menu' | 'dialog' | 'listbox'
  ariaLabel?: string
}

export function Popover({
  anchorRef,
  open,
  onClose,
  children,
  side = 'bottom',
  align = 'start',
  offset = 6,
  className,
  matchWidth,
  autoFocus = true,
  role = 'menu',
  ariaLabel,
}: PopoverProps) {
  const panelRef = useRef<HTMLDivElement>(null)
  const [pos, setPos] = useState<{ top: number; left: number; width?: number } | null>(null)

  const place = useCallback(() => {
    const anchor = anchorRef.current
    const panel = panelRef.current
    if (!anchor || !panel) return
    const a = anchor.getBoundingClientRect()
    const p = panel.getBoundingClientRect()
    const vw = window.innerWidth
    const vh = window.innerHeight
    const margin = 8

    let top = side === 'bottom' ? a.bottom + offset : a.top - p.height - offset
    if (top + p.height > vh - margin) top = a.top - p.height - offset
    if (top < margin) top = margin

    let left =
      align === 'start' ? a.left : align === 'end' ? a.right - p.width : a.left + a.width / 2 - p.width / 2
    left = Math.min(Math.max(margin, left), Math.max(margin, vw - p.width - margin))

    setPos({ top, left, width: matchWidth ? a.width : undefined })
  }, [align, anchorRef, matchWidth, offset, side])

  useLayoutEffect(() => {
    if (!open) {
      setPos(null)
      return
    }
    place()
  }, [open, place])

  useEffect(() => {
    if (!open) return
    const onScroll = () => place()
    window.addEventListener('resize', onScroll)
    window.addEventListener('scroll', onScroll, true)
    return () => {
      window.removeEventListener('resize', onScroll)
      window.removeEventListener('scroll', onScroll, true)
    }
  }, [open, place])

  useEffect(() => {
    if (!open) return
    const onPointerDown = (e: PointerEvent) => {
      const target = e.target as Node
      if (panelRef.current?.contains(target)) return
      if (anchorRef.current?.contains(target)) return
      onClose()
    }
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.stopPropagation()
        onClose()
        anchorRef.current?.focus()
      }
    }
    document.addEventListener('pointerdown', onPointerDown, true)
    document.addEventListener('keydown', onKey, true)
    return () => {
      document.removeEventListener('pointerdown', onPointerDown, true)
      document.removeEventListener('keydown', onKey, true)
    }
  }, [open, onClose, anchorRef])

  useEffect(() => {
    if (!open || !autoFocus) return
    const t = window.setTimeout(() => {
      const panel = panelRef.current
      if (!panel) return
      const focusable = panel.querySelector<HTMLElement>(
        '[data-autofocus], input, button:not([disabled]), [tabindex]:not([tabindex="-1"])',
      )
      focusable?.focus()
    }, 0)
    return () => window.clearTimeout(t)
  }, [open, autoFocus])

  if (!open) return null

  return createPortal(
    <div
      ref={panelRef}
      role={role}
      aria-label={ariaLabel}
      style={{
        top: pos?.top ?? -9999,
        left: pos?.left ?? -9999,
        width: pos?.width,
        visibility: pos ? 'visible' : 'hidden',
      }}
      className={cn(
        'fixed z-[70] origin-top rounded-lg border border-line-soft bg-elevated py-2 shadow-pop',
        'animate-pop-in text-sm text-ink',
        className,
      )}
    >
      {children}
    </div>,
    document.body,
  )
}

/* -------------------------------------------------------------------------- */
/*  Menu                                                                       */
/* -------------------------------------------------------------------------- */

export type MenuEntry =
  | {
      type?: 'item'
      id: string
      label: ReactNode
      icon?: ReactNode
      shortcut?: string
      onSelect: () => void
      disabled?: boolean
      danger?: boolean
      checked?: boolean
    }
  | { type: 'separator'; id: string }
  | { type: 'header'; id: string; label: string }

interface MenuProps {
  anchorRef: RefObject<HTMLElement | null>
  open: boolean
  onClose: () => void
  entries: MenuEntry[]
  align?: Align
  side?: Side
  className?: string
  ariaLabel?: string
}

export function Menu({
  anchorRef,
  open,
  onClose,
  entries,
  align = 'start',
  side = 'bottom',
  className,
  ariaLabel,
}: MenuProps) {
  const itemRefs = useRef<(HTMLButtonElement | null)[]>([])

  const selectable = entries
    .map((e, i) => ({ e, i }))
    .filter(({ e }) => (!e.type || e.type === 'item') && !('disabled' in e && e.disabled))

  const move = (dir: 1 | -1) => {
    const active = document.activeElement
    const currentIdx = selectable.findIndex(({ i }) => itemRefs.current[i] === active)
    const nextIdx =
      currentIdx === -1
        ? dir === 1
          ? 0
          : selectable.length - 1
        : (currentIdx + dir + selectable.length) % selectable.length
    itemRefs.current[selectable[nextIdx]?.i]?.focus()
  }

  return (
    <Popover
      anchorRef={anchorRef}
      open={open}
      onClose={onClose}
      align={align}
      side={side}
      className={cn('min-w-56 max-w-[min(20rem,92vw)]', className)}
      ariaLabel={ariaLabel}
    >
      <div
        onKeyDown={(e) => {
          if (e.key === 'ArrowDown') {
            e.preventDefault()
            move(1)
          } else if (e.key === 'ArrowUp') {
            e.preventDefault()
            move(-1)
          }
        }}
      >
        {entries.map((entry, i) => {
          if (entry.type === 'separator') {
            return <div key={entry.id} className="my-1.5 h-px bg-line-soft" />
          }
          if (entry.type === 'header') {
            return (
              <div
                key={entry.id}
                className="px-4 pb-1 pt-1.5 text-[11px] font-semibold uppercase tracking-wide text-ink-4"
              >
                {entry.label}
              </div>
            )
          }
          return (
            <button
              key={entry.id}
              ref={(el) => {
                itemRefs.current[i] = el
              }}
              type="button"
              role="menuitem"
              disabled={entry.disabled}
              onClick={() => {
                onClose()
                entry.onSelect()
              }}
              className={cn(
                'flex w-full items-center gap-3 px-4 py-[7px] text-left text-[13px] leading-5',
                'hover:bg-surface-2 focus:bg-surface-2 focus:outline-none',
                entry.disabled && 'pointer-events-none opacity-40',
                entry.danger && 'text-danger',
              )}
            >
              {entry.icon !== undefined && (
                <span className="flex h-4 w-4 shrink-0 items-center justify-center text-ink-3 [&_svg]:h-[18px] [&_svg]:w-[18px]">
                  {entry.icon}
                </span>
              )}
              <span className="min-w-0 flex-1 truncate">{entry.label}</span>
              {entry.checked && <span className="text-accent-ink">✓</span>}
              {entry.shortcut && (
                <span className="shrink-0 text-[11px] text-ink-4">{entry.shortcut}</span>
              )}
            </button>
          )
        })}
      </div>
    </Popover>
  )
}

import {
  forwardRef,
  useEffect,
  useId,
  useRef,
  useState,
  type ButtonHTMLAttributes,
  type ReactNode,
} from 'react'
import { createPortal } from 'react-dom'
import { Check, Minus } from 'lucide-react'
import { avatarColor, cn, initials } from '@/lib/utils'

/* -------------------------------------------------------------------------- */
/*  Tooltip                                                                    */
/* -------------------------------------------------------------------------- */

interface TooltipState {
  text: string
  x: number
  y: number
  below: boolean
}

let tooltipTimer: number | undefined

export function Tooltip({
  label,
  shortcut,
  children,
  disabled,
}: {
  label?: string
  shortcut?: string
  children: ReactNode
  disabled?: boolean
}) {
  const ref = useRef<HTMLSpanElement>(null)
  const [state, setState] = useState<TooltipState | null>(null)

  useEffect(() => () => window.clearTimeout(tooltipTimer), [])

  if (!label || disabled) return <>{children}</>

  const open = () => {
    window.clearTimeout(tooltipTimer)
    tooltipTimer = window.setTimeout(() => {
      const el = ref.current?.firstElementChild ?? ref.current
      if (!el) return
      const r = el.getBoundingClientRect()
      const below = r.bottom + 44 < window.innerHeight
      setState({
        text: shortcut ? `${label} (${shortcut})` : label,
        x: r.left + r.width / 2,
        y: below ? r.bottom + 8 : r.top - 8,
        below,
      })
    }, 450)
  }
  const close = () => {
    window.clearTimeout(tooltipTimer)
    setState(null)
  }

  return (
    <>
      <span
        ref={ref}
        className="contents"
        onPointerEnter={open}
        onPointerLeave={close}
        onPointerDown={close}
        onFocus={open}
        onBlur={close}
      >
        {children}
      </span>
      {state &&
        createPortal(
          <div
            role="tooltip"
            style={{
              left: state.x,
              top: state.y,
              transform: `translate(-50%, ${state.below ? '0' : '-100%'})`,
            }}
            className="pointer-events-none fixed z-[90] animate-fade-in whitespace-nowrap rounded bg-[#3c4043] px-2 py-1 text-[11px] font-medium text-white shadow-pop dark:bg-[#e3e3e3] dark:text-[#1f1f1f]"
          >
            {state.text}
          </div>,
          document.body,
        )}
    </>
  )
}

/* -------------------------------------------------------------------------- */
/*  Buttons                                                                    */
/* -------------------------------------------------------------------------- */

interface IconButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  label: string
  shortcut?: string
  size?: 'sm' | 'md' | 'lg'
  active?: boolean
  showTooltip?: boolean
}

export const IconButton = forwardRef<HTMLButtonElement, IconButtonProps>(function IconButton(
  { label, shortcut, size = 'md', active, className, children, showTooltip = true, ...rest },
  ref,
) {
  const button = (
    <button
      ref={ref}
      type="button"
      aria-label={label}
      className={cn(
        'inline-flex shrink-0 items-center justify-center rounded-full text-ink-2 transition-colors',
        'hover:bg-surface-3 hover:text-ink active:bg-surface-3 disabled:pointer-events-none disabled:opacity-35',
        size === 'sm' && 'h-7 w-7 [&_svg]:h-4 [&_svg]:w-4',
        size === 'md' && 'h-9 w-9 [&_svg]:h-5 [&_svg]:w-5',
        size === 'lg' && 'h-10 w-10 [&_svg]:h-[22px] [&_svg]:w-[22px]',
        active && 'bg-surface-3 text-ink',
        className,
      )}
      {...rest}
    >
      {children}
    </button>
  )
  return showTooltip ? (
    <Tooltip label={label} shortcut={shortcut}>
      {button}
    </Tooltip>
  ) : (
    button
  )
})

export const Button = forwardRef<
  HTMLButtonElement,
  ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'filled' | 'tonal' | 'text' | 'outline' }
>(function Button({ variant = 'filled', className, ...rest }, ref) {
  return (
    <button
      ref={ref}
      type="button"
      className={cn(
        'inline-flex h-9 items-center justify-center gap-2 rounded-full px-5 text-[13px] font-medium transition-colors',
        'disabled:pointer-events-none disabled:opacity-40 [&_svg]:h-[18px] [&_svg]:w-[18px]',
        variant === 'filled' && 'bg-accent text-on-accent hover:bg-accent-hover',
        variant === 'tonal' && 'bg-accent-soft text-accent-ink hover:brightness-95',
        variant === 'text' && 'px-3 text-accent-ink hover:bg-accent-soft/40',
        variant === 'outline' && 'border border-line text-ink hover:bg-surface-2',
        className,
      )}
      {...rest}
    />
  )
})

/* -------------------------------------------------------------------------- */
/*  Checkbox / Switch                                                          */
/* -------------------------------------------------------------------------- */

export function Checkbox({
  checked,
  indeterminate,
  onChange,
  label,
  className,
  stopPropagation = true,
}: {
  checked: boolean
  indeterminate?: boolean
  onChange: (next: boolean, event: React.MouseEvent) => void
  label: string
  className?: string
  stopPropagation?: boolean
}) {
  return (
    <button
      type="button"
      role="checkbox"
      aria-checked={indeterminate ? 'mixed' : checked}
      aria-label={label}
      onClick={(e) => {
        if (stopPropagation) e.stopPropagation()
        onChange(!checked, e)
      }}
      className={cn(
        'inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-full text-ink-3 hover:bg-surface-3',
        className,
      )}
    >
      <span
        className={cn(
          'flex h-[18px] w-[18px] items-center justify-center rounded-[3px] border-2 transition-colors',
          checked || indeterminate
            ? 'border-accent bg-accent text-on-accent'
            : 'border-current bg-transparent',
        )}
      >
        {indeterminate ? (
          <Minus className="h-3 w-3" strokeWidth={3} />
        ) : checked ? (
          <Check className="h-3 w-3" strokeWidth={3.5} />
        ) : null}
      </span>
    </button>
  )
}

export function Switch({
  checked,
  onChange,
  label,
}: {
  checked: boolean
  onChange: (next: boolean) => void
  label: string
}) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      aria-label={label}
      onClick={() => onChange(!checked)}
      className={cn(
        'relative h-[18px] w-[34px] shrink-0 rounded-full transition-colors',
        checked ? 'bg-accent' : 'bg-line',
      )}
    >
      <span
        className={cn(
          'absolute top-1/2 h-[14px] w-[14px] -translate-y-1/2 rounded-full bg-white shadow transition-[left]',
          checked ? 'left-[18px]' : 'left-[2px]',
        )}
      />
    </button>
  )
}

export function Radio({
  checked,
  onChange,
  label,
  description,
}: {
  checked: boolean
  onChange: () => void
  label: ReactNode
  description?: ReactNode
}) {
  const id = useId()
  return (
    <label
      htmlFor={id}
      className="flex cursor-pointer items-start gap-3 rounded-lg px-2 py-1.5 hover:bg-surface-2"
    >
      <input
        id={id}
        type="radio"
        checked={checked}
        onChange={onChange}
        className="mt-[3px] h-4 w-4 shrink-0 accent-[var(--color-accent)]"
      />
      <span className="min-w-0">
        <span className="block text-[13px] leading-5 text-ink">{label}</span>
        {description && (
          <span className="mt-0.5 block text-[12px] leading-4 text-ink-3">{description}</span>
        )}
      </span>
    </label>
  )
}

