import { matchesQuery, parseQuery, queryScope, type Query } from './search'
import {
  SYSTEM,
  type Category,
  type Draft,
  type Label,
  type MailData,
  type Message,
  type Thread,
  type ViewId,
} from './types'
import { htmlToText, shortName, truncate } from './utils'

export interface ThreadSummary {
  id: string
  subject: string
  snippet: string
  messages: Message[]
  count: number
  date: string
  unread: boolean
  starred: boolean
  important: boolean
  hasAttachment: boolean
  attachmentNames: string[]
  userLabels: Label[]
  category: Category
  snoozedUntil?: string
  scheduledFor?: string
  draftId?: string
  /** e.g. "Priya, me" — chronological, deduped. */
  senders: string
  /** e.g. "Harper, Marcus" — for Sent-style views. */
  recipients: string
  lastFromMe: boolean
}

function joinPeople(names: string[]) {
  if (names.length <= 3) return names.join(', ')
  return `${names[0]}, ${names[1]} .. ${names[names.length - 1]}`
}

export function summarize(
  thread: Thread,
  data: MailData,
  labelById: Map<string, Label>,
  draftByThread: Map<string, string>,
): ThreadSummary {
  const me = data.account.email
  const messages = thread.messageIds
    .map((id) => data.messages[id])
    .filter(Boolean)
    .sort((a, b) => Date.parse(a.date) - Date.parse(b.date))

  const last = messages[messages.length - 1]
  const senderNames: string[] = []
  const recipientNames: string[] = []
  for (const m of messages) {
    const s = shortName(m.from, me)
    if (!senderNames.includes(s)) senderNames.push(s)
    for (const r of m.to) {
      const n = shortName(r, me)
      if (n !== 'me' && !recipientNames.includes(n)) recipientNames.push(n)
    }
  }

  const attachmentNames = messages.flatMap((m) => m.attachments.map((a) => a.name))

  return {
    id: thread.id,
    subject: thread.subject,
    snippet: last ? truncate(htmlToText(last.bodyHtml), 220) : '',
    messages,
    count: messages.length,
    date: last?.date ?? new Date(0).toISOString(),
    unread: messages.some((m) => !m.read),
    starred: messages.some((m) => m.starred),
    important: thread.labelIds.includes(SYSTEM.important),
    hasAttachment: attachmentNames.length > 0,
    attachmentNames,
    userLabels: thread.labelIds
      .map((id) => labelById.get(id))
      .filter((l): l is Label => Boolean(l)),
    category: thread.category,
    snoozedUntil: thread.snoozedUntil,
    scheduledFor: messages.find((m) => m.scheduledFor)?.scheduledFor,
    draftId: draftByThread.get(thread.id),
    senders: joinPeople(senderNames),
    recipients: joinPeople(recipientNames.length ? recipientNames : ['(no recipients)']),
    lastFromMe: Boolean(last?.outgoing),
  }
}

/* -------------------------------------------------------------------------- */
/*  View predicates                                                            */
/* -------------------------------------------------------------------------- */

const isIn = (t: Thread, l: string) => t.labelIds.includes(l)

function hasStar(t: Thread, data: MailData) {
  return t.messageIds.some((id) => data.messages[id]?.starred)
}

function hasSent(t: Thread, data: MailData) {
  return t.messageIds.some((id) => {
    const m = data.messages[id]
    return m?.outgoing && !m.scheduledFor
  })
}

function isSnoozed(t: Thread, now: number) {
  return Boolean(t.snoozedUntil && Date.parse(t.snoozedUntil) > now)
}

export function viewPredicate(view: ViewId, data: MailData, now: number) {
  switch (view) {
    case 'inbox':
      return (t: Thread) =>
        isIn(t, SYSTEM.inbox) && !isIn(t, SYSTEM.trash) && !isIn(t, SYSTEM.spam) && !isSnoozed(t, now)
    case 'starred':
      return (t: Thread) => hasStar(t, data) && !isIn(t, SYSTEM.trash) && !isIn(t, SYSTEM.spam)
    case 'snoozed':
      return (t: Thread) => isSnoozed(t, now) && !isIn(t, SYSTEM.trash)
    case 'important':
      return (t: Thread) =>
        isIn(t, SYSTEM.important) && !isIn(t, SYSTEM.trash) && !isIn(t, SYSTEM.spam)
    case 'sent':
      return (t: Thread) => hasSent(t, data) && !isIn(t, SYSTEM.trash) && !isIn(t, SYSTEM.spam)
    case 'scheduled':
      return (t: Thread) => isIn(t, SYSTEM.scheduled) && !isIn(t, SYSTEM.trash)
    case 'spam':
      return (t: Thread) => isIn(t, SYSTEM.spam)
    case 'trash':
      return (t: Thread) => isIn(t, SYSTEM.trash)
    case 'all':
      return (t: Thread) => !isIn(t, SYSTEM.trash) && !isIn(t, SYSTEM.spam)
    case 'drafts':
      return () => false
  }
}

export function labelPredicate(labelId: string) {
  return (t: Thread) =>
    t.labelIds.includes(labelId) && !isIn(t, SYSTEM.trash) && !isIn(t, SYSTEM.spam)
}

/** The scope a bare search runs over: everything except trash and spam. */
export function searchPredicate(q: Query, data: MailData, now: number) {
  const scope = queryScope(q)
  if (scope === 'anywhere') return () => true
  if (scope === 'default') return (t: Thread) => !isIn(t, SYSTEM.trash) && !isIn(t, SYSTEM.spam)
  if (scope === 'drafts') return () => false
  return viewPredicate(scope as ViewId, data, now)
}

/* -------------------------------------------------------------------------- */
/*  Counts                                                                     */
/* -------------------------------------------------------------------------- */

export interface Counts {
  inboxUnread: number
  inboxTotal: number
  starred: number
  snoozed: number
  important: number
  drafts: number
  scheduled: number
  spam: number
  trash: number
  sent: number
  byCategory: Record<Category, { total: number; unread: number }>
  byLabel: Record<string, { total: number; unread: number }>
}

export function computeCounts(data: MailData, now: number): Counts {
  const byCategory = {
    primary: { total: 0, unread: 0 },
    social: { total: 0, unread: 0 },
    promotions: { total: 0, unread: 0 },
    updates: { total: 0, unread: 0 },
    forums: { total: 0, unread: 0 },
  } as Record<Category, { total: number; unread: number }>
  const byLabel: Record<string, { total: number; unread: number }> = {}
  for (const l of data.labels) byLabel[l.id] = { total: 0, unread: 0 }

  const counts: Counts = {
    inboxUnread: 0,
    inboxTotal: 0,
    starred: 0,
    snoozed: 0,
    important: 0,
    drafts: Object.keys(data.drafts).length,
    scheduled: 0,
    spam: 0,
    trash: 0,
    sent: 0,
    byCategory,
    byLabel,
  }

  const inbox = viewPredicate('inbox', data, now)
  for (const t of Object.values(data.threads)) {
    const unread = t.messageIds.some((id) => {
      const m = data.messages[id]
      return m && !m.read
    })
    if (inbox(t)) {
      counts.inboxTotal += 1
      if (unread) counts.inboxUnread += 1
      byCategory[t.category].total += 1
      if (unread) byCategory[t.category].unread += 1
    }
    if (isIn(t, SYSTEM.trash)) counts.trash += 1
    else if (isIn(t, SYSTEM.spam)) counts.spam += 1
    else {
      if (hasStar(t, data)) counts.starred += 1
      if (isSnoozed(t, now)) counts.snoozed += 1
      if (isIn(t, SYSTEM.important)) counts.important += 1
      if (hasSent(t, data)) counts.sent += 1
      for (const id of t.labelIds) {
        if (byLabel[id]) {
          byLabel[id].total += 1
          if (unread) byLabel[id].unread += 1
        }
      }
    }
    if (isIn(t, SYSTEM.scheduled) && !isIn(t, SYSTEM.trash)) counts.scheduled += 1
  }
  return counts
}

/* -------------------------------------------------------------------------- */
/*  List building                                                              */
/* -------------------------------------------------------------------------- */

export interface ListRequest {
  view: ViewId
  labelId?: string
  searchText?: string
  category?: Category
  now: number
}

export interface ListResult {
  threads: ThreadSummary[]
  drafts: Draft[]
  query: Query | null
}

export function buildList(data: MailData, req: ListRequest): ListResult {
  const labelById = new Map(data.labels.map((l) => [l.id, l]))
  const labelsByName = new Map(data.labels.map((l) => [l.name.toLowerCase(), l]))
  const draftByThread = new Map<string, string>()
  for (const d of Object.values(data.drafts)) if (d.threadId) draftByThread.set(d.threadId, d.id)

  const searchText = req.searchText?.trim()
  const query = searchText ? parseQuery(searchText, req.now) : null

  let threads: Thread[]
  let drafts: Draft[] = []

  if (query && !query.empty) {
    const scope = searchPredicate(query, data, req.now)
    threads = Object.values(data.threads).filter(
      (t) => scope(t) && matchesQuery(t, query, data, labelsByName),
    )
    drafts = Object.values(data.drafts).filter((d) => draftMatches(d, query, data))
  } else if (req.view === 'drafts') {
    threads = []
    drafts = Object.values(data.drafts)
  } else if (req.labelId) {
    const pred = labelPredicate(req.labelId)
    threads = Object.values(data.threads).filter(pred)
  } else {
    const pred = viewPredicate(req.view, data, req.now)
    threads = Object.values(data.threads).filter(pred)
    if (req.view === 'inbox' && req.category) {
      threads = threads.filter((t) => t.category === req.category)
    }
  }

  const summaries = threads.map((t) => summarize(t, data, labelById, draftByThread))

  if (req.view === 'scheduled' && !query) {
    summaries.sort((a, b) => Date.parse(a.scheduledFor ?? a.date) - Date.parse(b.scheduledFor ?? b.date))
  } else if (req.view === 'snoozed' && !query) {
    summaries.sort((a, b) => Date.parse(a.snoozedUntil ?? a.date) - Date.parse(b.snoozedUntil ?? b.date))
  } else {
    summaries.sort((a, b) => Date.parse(b.date) - Date.parse(a.date))
  }

  drafts = [...drafts].sort((a, b) => Date.parse(b.updatedAt) - Date.parse(a.updatedAt))

  return { threads: summaries, drafts, query }
}

function draftMatches(d: Draft, q: Query, data: MailData) {
  if (q.in && q.in !== 'drafts' && q.in !== 'anywhere') return false
  if (q.isStarred || q.isImportant || q.isSnoozed || q.isRead) return false
  if (q.hasAttachment && !d.attachments.length) return false
  if (q.subject && !d.subject.toLowerCase().includes(q.subject)) return false
  if (q.from && q.from !== 'me' && !data.account.email.includes(q.from)) return false
  if (q.to && !d.to.some((a) => a.email.toLowerCase().includes(q.to!) || a.name.toLowerCase().includes(q.to!)))
    return false
  if (q.labelNames.length) return false
  const hay = `${d.subject} ${htmlToText(d.bodyHtml)} ${d.to.map((a) => `${a.name} ${a.email}`).join(' ')}`.toLowerCase()
  for (const t of q.terms) if (!hay.includes(t)) return false
  for (const p of q.phrases) if (!hay.includes(p)) return false
  return true
}

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react'
import * as M from '@/lib/mutations'
import type { Address, ComposeMode, Draft, MailData, Message, Thread } from '@/lib/types'
import { formatFullDate, htmlToText, uid } from '@/lib/utils'
import { useMail } from './mail-store'
import { useSettings } from './settings'

export type WindowState = 'normal' | 'minimized' | 'full'

export interface ComposeWindow {
  draft: Draft
  state: WindowState
  /** Bumped to pull focus to this window. */
  focusToken: number
}

interface ComposeContextValue {
  windows: ComposeWindow[]
  openNew: (seed?: Partial<Draft>) => void
  openDraft: (draftId: string) => void
  openReply: (thread: Thread, message: Message, mode: ComposeMode) => void
  update: (id: string, patch: Partial<Draft>) => void
  setState: (id: string, state: WindowState) => void
  focus: (id: string) => void
  close: (id: string) => void
  discard: (id: string) => void
  /** Returns the draft that was sent so callers can build a toast. */
  send: (id: string, scheduledFor?: string) => { threadId: string; draft: Draft } | null
  isEmpty: (d: Draft) => boolean
}

const ComposeContext = createContext<ComposeContextValue | null>(null)

const MAX_OPEN = 3

function emptyDraft(seed?: Partial<Draft>): Draft {
  return {
    id: uid('d'),
    mode: 'new',
    to: [],
    cc: [],
    bcc: [],
    subject: '',
    bodyHtml: '',
    attachments: [],
    updatedAt: new Date().toISOString(),
    ...seed,
  }
}

function signatureBlock(sig: string) {
  return sig.trim()
    ? `<p><br></p><p class="sig" style="color:#80868b">--<br>${sig
        .split('\n')
        .map((l) => l.trim())
        .join('<br>')}</p>`
    : '<p><br></p>'
}

function quotedBlock(m: Message) {
  const who = m.from.name ? `${m.from.name} &lt;${m.from.email}&gt;` : m.from.email
  return `<p><br></p><div class="quoted"><p>On ${formatFullDate(m.date)}, ${who} wrote:</p>${m.bodyHtml}</div>`
}

function replyRecipients(m: Message, mode: ComposeMode, me: string) {
  const dedupe = (list: Address[]) => {
    const seen = new Set<string>()
    return list.filter((a) => {
      const k = a.email.toLowerCase()
      if (k === me.toLowerCase() || seen.has(k)) return false
      seen.add(k)
      return true
    })
  }
  if (mode === 'forward') return { to: [] as Address[], cc: [] as Address[] }
  const primary = m.outgoing ? m.to : [m.from]
  if (mode === 'reply') return { to: dedupe(primary), cc: [] as Address[] }
  return { to: dedupe(primary), cc: dedupe([...m.to, ...m.cc]) }
}

function replySubject(subject: string, mode: ComposeMode) {
  const stripped = subject.replace(/^((re|fwd):\s*)+/i, '')
  return mode === 'forward' ? `Fwd: ${stripped}` : `Re: ${stripped}`
}

export function ComposeProvider({ children }: { children: ReactNode }) {
  const { data, mutate } = useMail()
  const { settings } = useSettings()
  const [windows, setWindows] = useState<ComposeWindow[]>([])
  const focusCounter = useRef(1)
  const syncTimers = useRef(new Map<string, number>())
  const dataRef = useRef(data)
  dataRef.current = data

  /** Write the live draft back to the persisted store, debounced. */
  const scheduleSync = useCallback(
    (draft: Draft) => {
      const timers = syncTimers.current
      window.clearTimeout(timers.get(draft.id))
      timers.set(
        draft.id,
        window.setTimeout(() => {
          timers.delete(draft.id)
          mutate((d) => M.upsertDraft(d, draft))
        }, 500),
      )
    },
    [mutate],
  )

  const flushSync = useCallback(
    (draft: Draft) => {
      window.clearTimeout(syncTimers.current.get(draft.id))
      syncTimers.current.delete(draft.id)
      mutate((d) => M.upsertDraft(d, draft))
    },
    [mutate],
  )

  const push = useCallback((draft: Draft, state: WindowState = 'normal') => {
    focusCounter.current += 1
    setWindows((list) => {
      const existing = list.find((w) => w.draft.id === draft.id)
      if (existing) {
        return list.map((w) =>
          w.draft.id === draft.id
            ? { ...w, state: w.state === 'minimized' ? 'normal' : w.state, focusToken: focusCounter.current }
            : w,
        )
      }
      const next = [...list, { draft, state, focusToken: focusCounter.current }]
      // Older windows collapse rather than disappear once the deck is full.
      if (next.length > MAX_OPEN) {
        const overflow = next.length - MAX_OPEN
        return next.map((w, i) => (i < overflow ? { ...w, state: 'minimized' as WindowState } : w))
      }
      return next
    })
  }, [])

  const openNew = useCallback(
    (seed?: Partial<Draft>) => {
      const draft = emptyDraft({
        bodyHtml: settings.signatureEnabled ? signatureBlock(settings.signature) : '',
        ...seed,
      })
      push(draft)
      scheduleSync(draft)
    },
    [push, scheduleSync, settings.signature, settings.signatureEnabled],
  )

  const openDraft = useCallback(
    (draftId: string) => {
      const draft = dataRef.current.drafts[draftId]
      if (draft) push({ ...draft })
    },
    [push],
  )

  const openReply = useCallback(
    (thread: Thread, message: Message, mode: ComposeMode) => {
      const me = dataRef.current.account.email
      const { to, cc } = replyRecipients(message, mode, me)
      const sig = settings.signatureEnabled ? signatureBlock(settings.signature) : '<p><br></p>'
      const draft = emptyDraft({
        threadId: mode === 'forward' ? undefined : thread.id,
        inReplyTo: message.id,
        mode,
        to,
        cc,
        subject: replySubject(thread.subject, mode),
        bodyHtml: `${sig}${quotedBlock(message)}`,
        attachments: mode === 'forward' ? message.attachments.map((a) => ({ ...a })) : [],
      })
      push(draft)
      scheduleSync(draft)
    },
    [push, scheduleSync, settings.signature, settings.signatureEnabled],
  )

  const update = useCallback(
    (id: string, patch: Partial<Draft>) => {
      setWindows((list) => {
        const next = list.map((w) =>
          w.draft.id === id ? { ...w, draft: { ...w.draft, ...patch } } : w,
        )
        const changed = next.find((w) => w.draft.id === id)
        if (changed) scheduleSync(changed.draft)
        return next
      })
    },
    [scheduleSync],
  )

  const setState = useCallback((id: string, state: WindowState) => {
    focusCounter.current += 1
    setWindows((list) =>
      list.map((w) => (w.draft.id === id ? { ...w, state, focusToken: focusCounter.current } : w)),
    )
  }, [])

  const focus = useCallback((id: string) => {
    focusCounter.current += 1
    setWindows((list) =>
      list.map((w) => (w.draft.id === id ? { ...w, focusToken: focusCounter.current } : w)),
    )
  }, [])

  const isEmpty = useCallback((d: Draft) => {
    const text = htmlToText(d.bodyHtml).replace(/^--[\s\S]*$/, '').trim()
    return (
      !d.to.length && !d.cc.length && !d.bcc.length && !d.subject.trim() && !text && !d.attachments.length
    )
  }, [])

  const close = useCallback(
    (id: string) => {
      const win = windows.find((w) => w.draft.id === id)
      setWindows((list) => list.filter((w) => w.draft.id !== id))
      if (!win) return
      window.clearTimeout(syncTimers.current.get(id))
      syncTimers.current.delete(id)
      if (isEmpty(win.draft)) mutate((d) => M.discardDraft(d, id))
      else mutate((d) => M.upsertDraft(d, win.draft))
    },
    [windows, mutate, isEmpty],
  )

  const discard = useCallback(
    (id: string) => {
      window.clearTimeout(syncTimers.current.get(id))
      syncTimers.current.delete(id)
      setWindows((list) => list.filter((w) => w.draft.id !== id))
      mutate((d) => M.discardDraft(d, id), 'Draft discarded')
    },
    [mutate],
  )

  const send = useCallback(
    (id: string, scheduledFor?: string) => {
      const win = windows.find((w) => w.draft.id === id)
      if (!win) return null
      const draft = win.draft
      window.clearTimeout(syncTimers.current.get(id))
      syncTimers.current.delete(id)
      setWindows((list) => list.filter((w) => w.draft.id !== id))

      let threadId = ''
      mutate((d: MailData) => {
        const result = M.sendDraft(d, draft, { scheduledFor })
        threadId = result.threadId
      }, scheduledFor ? 'Message scheduled' : 'Message sent')
      return { threadId, draft }
    },
    [windows, mutate],
  )

  useEffect(() => {
    const timers = syncTimers.current
    return () => timers.forEach((t) => window.clearTimeout(t))
  }, [])

  // Warn only when there is unsaved work in flight.
  useEffect(() => {
    if (!windows.length) return
    const handler = () => {
      windows.forEach((w) => flushSync(w.draft))
    }
    window.addEventListener('beforeunload', handler)
    return () => window.removeEventListener('beforeunload', handler)
  }, [windows, flushSync])

  const value = useMemo(
    () => ({
      windows,
      openNew,
      openDraft,
      openReply,
      update,
      setState,
      focus,
      close,
      discard,
      send,
      isEmpty,
    }),
    [windows, openNew, openDraft, openReply, update, setState, focus, close, discard, send, isEmpty],
  )

  return <ComposeContext.Provider value={value}>{children}</ComposeContext.Provider>
}

export function useCompose() {
  const ctx = useContext(ComposeContext)
  if (!ctx) throw new Error('useCompose must be used inside <ComposeProvider>')
  return ctx
}

import { useCallback, useEffect, useState } from 'react'
import type { Category, ViewId } from '@/lib/types'

export interface Route {
  view: ViewId
  labelId?: string
  search?: string
  threadId?: string
  /** Settings tab id; the settings screen replaces the list when set. */
  settingsTab?: string
  category?: Category
}

const VIEWS: ViewId[] = [
  'inbox',
  'starred',
  'snoozed',
  'important',
  'sent',
  'scheduled',
  'drafts',
  'all',
  'spam',
  'trash',
]

export function parseHash(hash: string): Route {
  const raw = hash.replace(/^#\/?/, '')
  const [pathPart, queryPart] = raw.split('?')
  const params = new URLSearchParams(queryPart ?? '')
  const segments = pathPart.split('/').filter(Boolean).map(decodeURIComponent)

  const route: Route = { view: 'inbox' }
  const head = segments[0]

  if (head === 'settings') {
    route.settingsTab = segments[1] || 'general'
    return route
  }
  if (head === 'label' && segments[1]) {
    route.labelId = segments[1]
    route.view = 'all'
    route.threadId = segments[2]
  } else if (head === 'search') {
    route.view = 'all'
    route.search = params.get('q') ?? ''
    route.threadId = segments[1]
  } else if (head && (VIEWS as string[]).includes(head)) {
    route.view = head as ViewId
    route.threadId = segments[1]
  }

  const cat = params.get('cat')
  if (cat) route.category = cat as Category
  return route
}

export function serializeRoute(r: Route): string {
  if (r.settingsTab) return `#/settings/${r.settingsTab}`
  const params = new URLSearchParams()
  let path: string
  if (r.search !== undefined) {
    path = 'search'
    params.set('q', r.search)
  } else if (r.labelId) {
    path = `label/${encodeURIComponent(r.labelId)}`
  } else {
    path = r.view
  }
  if (r.threadId) path += `/${encodeURIComponent(r.threadId)}`
  if (r.category && r.view === 'inbox' && !r.search && !r.labelId) params.set('cat', r.category)
  const q = params.toString()
  return `#/${path}${q ? `?${q}` : ''}`
}

export function useRouter() {
  const [route, setRoute] = useState<Route>(() => parseHash(window.location.hash))

  useEffect(() => {
    const onChange = () => setRoute(parseHash(window.location.hash))
    window.addEventListener('hashchange', onChange)
    if (!window.location.hash) window.location.replace('#/inbox')
    return () => window.removeEventListener('hashchange', onChange)
  }, [])

  const navigate = useCallback((next: Route, replace = false) => {
    const hash = serializeRoute(next)
    if (hash === window.location.hash) {
      setRoute(next)
      return
    }
    if (replace) window.history.replaceState(null, '', hash)
    else window.history.pushState(null, '', hash)
    setRoute(parseHash(hash))
  }, [])

  const back = useCallback(() => window.history.back(), [])

  return { route, navigate, back }
}

import {
  createContext,
