  anchorRef: React.RefObject<HTMLElement | null>
  open: boolean
  onClose: () => void
  onPick: (iso: string, human: string) => void
  align?: 'start' | 'end' | 'center'
  /** Confirm-button label in the custom picker. */
  verb?: string
  title?: string
}

