  const inTrash = view === 'trash'
  const people = view === 'sent' || view === 'scheduled' ? s.recipients : s.senders
  const primary = s.messages[s.messages.length - 1]

  const stamp =
    view === 'scheduled' && s.scheduledFor
      ? formatFuture(s.scheduledFor, nowDate)
      : view === 'snoozed' && s.snoozedUntil
        ? formatFuture(s.snoozedUntil, nowDate)
        : formatListDate(s.date, nowDate)

  return (
    <li
      className={cn(
        'group relative border-b border-line-soft/70 transition-colors',
        selected
          ? 'bg-select'
          : s.unread
            ? 'bg-unread hover:z-[1] hover:shadow-row'
            : 'bg-read hover:z-[1] hover:shadow-row',
        cursor && 'ring-1 ring-inset ring-accent/45',
      )}
    >
      <div
        role="button"
        tabIndex={-1}
        aria-label={s.subject || '(no subject)'}
        onClick={() => handlers.onOpen(s.id)}
        className={cn(
          'flex cursor-pointer items-start gap-1 pl-1 pr-2 sm:items-center sm:pl-2 sm:pr-3',
          DENSITY_ROW[density],
        )}
      >
        <button
          type="button"
          aria-label={selected ? 'Deselect' : 'Select'}
          onClick={(e) => {
            e.stopPropagation()
            handlers.onSelect(s.id, !selected, e.shiftKey)
          }}
          className="mt-0.5 shrink-0 rounded-full p-0.5 sm:hidden"
        >
          {selected ? (
            <span className="flex h-9 w-9 items-center justify-center rounded-full bg-accent text-on-accent">
              ✓
            </span>
          ) : (
            <Avatar
              name={primary?.from.name ?? ''}
              email={primary?.from.email ?? ''}
              size={36}
            />
          )}
        </button>

        <Checkbox
          checked={selected}
          label={selected ? 'Deselect conversation' : 'Select conversation'}
          onChange={(next, e) => handlers.onSelect(s.id, next, e.shiftKey)}
          className="hidden shrink-0 sm:inline-flex"
        />
        <button
          type="button"
          aria-label={s.starred ? 'Remove star' : 'Add star'}
          onClick={(e) => {
            e.stopPropagation()
            handlers.onStar(s.id, !s.starred)
          }}
          className="hidden h-8 w-8 shrink-0 items-center justify-center rounded-full text-ink-4 hover:bg-surface-3 sm:inline-flex"
        >
          <Star
            className={cn('h-[18px] w-[18px]', s.starred && 'fill-star text-star')}
          />
        </button>
        <button
          type="button"
          aria-label={s.important ? 'Mark not important' : 'Mark important'}
          onClick={(e) => {
            e.stopPropagation()
            handlers.onImportant(s.id, !s.important)
          }}
          className="hidden h-8 w-8 shrink-0 items-center justify-center rounded-full text-ink-4 hover:bg-surface-3 lg:inline-flex"
        >
          <svg viewBox="0 0 24 24" className="h-[18px] w-[18px]">
            <path
              d="M6.5 5h11.2l-3.6 7 3.6 7H6.5V5z"
              className={cn(s.important ? 'fill-important stroke-important' : 'fill-none stroke-current')}
              strokeWidth="1.6"
              strokeLinejoin="round"
            />
          </svg>
        </button>

        <div className="min-w-0 flex-1 py-0.5 sm:flex sm:items-center sm:gap-2 sm:py-0">
          {/* Mobile: two-line layout */}
          <div className="sm:hidden">
            <div className="flex items-baseline gap-2">
              <span
                className={cn(
                  'min-w-0 flex-1 truncate text-[14px]',
                  s.unread ? 'font-bold text-ink' : 'text-ink-2',
                )}
              >
                {people}
                {s.count > 1 && <span className="ml-1 text-ink-4">{s.count}</span>}
              </span>
              <span
                className={cn(
                  'shrink-0 text-[11px]',
                  s.unread ? 'font-bold text-ink' : 'text-ink-3',
                )}
              >
                {stamp}
              </span>
            </div>
            <div
              className={cn(
                'mt-0.5 truncate text-[13px]',
                s.unread ? 'font-semibold text-ink' : 'text-ink-2',
              )}
            >
              <Highlight text={s.subject || '(no subject)'} terms={terms} />
            </div>
            {showPreview && (
              <div className="mt-0.5 flex items-center gap-1.5 truncate text-[12px] text-ink-3">
                {s.hasAttachment && <Paperclip className="h-3 w-3 shrink-0" />}
                <span className="truncate">
                  <Highlight text={s.snippet} terms={terms} />
                </span>
              </div>
            )}
            {s.userLabels.length > 0 && (
              <div className="mt-1 flex gap-1 overflow-hidden">
                {s.userLabels.slice(0, 3).map((l) => (
                  <LabelChip key={l.id} name={l.name} bg={l.color.bg} fg={l.color.fg} />
                ))}
              </div>
            )}
          </div>

          {/* Desktop: single-line layout */}
          <span
            className={cn(
              'hidden w-[10rem] shrink-0 truncate text-[14px] xl:w-[13rem] sm:block',
              s.unread ? 'font-bold text-ink' : 'text-ink-2',
            )}
          >
            {people}
            {s.count > 1 && <span className="ml-1 font-normal text-ink-4">{s.count}</span>}
          </span>
          <span className="hidden min-w-0 flex-1 items-center gap-1.5 sm:flex">
            {s.userLabels.slice(0, 3).map((l) => (
              <LabelChip key={l.id} name={l.name} bg={l.color.bg} fg={l.color.fg} />
            ))}
            <span className="min-w-0 truncate text-[14px]">
              <span className={cn(s.unread ? 'font-bold text-ink' : 'text-ink')}>
                <Highlight text={s.subject || '(no subject)'} terms={terms} />
              </span>
              {showPreview && s.snippet && (
                <span className={cn('text-ink-3', s.unread ? 'font-normal' : '')}>
                  {' — '}
                  <Highlight text={s.snippet} terms={terms} />
                </span>
              )}
            </span>
          </span>
        </div>

        <div className="relative hidden w-[8.5rem] shrink-0 items-center justify-end gap-0.5 self-stretch sm:flex">
          <span className="flex items-center gap-1.5 pr-1">
            {s.hasAttachment && (
              <Paperclip className={cn('h-4 w-4 shrink-0 text-ink-3', hoverActions && 'group-hover:hidden')} />
            )}
            <span
              className={cn(
                'text-[12px] tabular-nums',
                s.unread ? 'font-bold text-ink' : 'text-ink-3',
                hoverActions && 'group-hover:invisible',
              )}
            >
              {stamp}
            </span>
          </span>
          {hoverActions && (
            <div
              className="absolute inset-y-0 right-0 hidden items-center gap-0.5 pl-2 group-hover:flex group-focus-within:flex"
              onClick={(e) => e.stopPropagation()}
            >
              {inTrash ? (
                <IconButton
                  label="Move to inbox"
                  size="sm"
                  onClick={() => handlers.onUntrash(s.id)}
                >
                  <ArchiveRestore />
                </IconButton>
              ) : (
                <IconButton label="Archive" shortcut="E" size="sm" onClick={() => handlers.onArchive(s.id)}>
                  <Archive />
                </IconButton>
              )}
              <IconButton label="Delete" shortcut="#" size="sm" onClick={() => handlers.onTrash(s.id)}>
                <Trash2 />
              </IconButton>
              <IconButton
                label={s.unread ? 'Mark as read' : 'Mark as unread'}
                size="sm"
                onClick={() => handlers.onRead(s.id, s.unread)}
              >
                {s.unread ? <MailOpen /> : <Mail />}
              </IconButton>
              <IconButton
                ref={snoozeRef}
                label="Snooze"
                size="sm"
                onClick={() => setSnoozeOpen(true)}
                active={snoozeOpen}
              >
                <Clock />
              </IconButton>
            </div>
          )}
        </div>

        <ChevronRight className="mt-2 h-4 w-4 shrink-0 text-ink-4 sm:hidden" />
      </div>

      {(s.snoozedUntil || s.scheduledFor) && view !== 'snoozed' && view !== 'scheduled' && (
        <div className="pointer-events-none absolute bottom-0.5 left-[7.5rem] hidden text-[11px] text-important sm:block">
          {s.scheduledFor
            ? `Scheduled for ${formatFuture(s.scheduledFor, nowDate)}`
            : `Snoozed until ${formatFuture(s.snoozedUntil!, nowDate)}`}
        </div>
      )}

      <SnoozeMenu
        anchorRef={snoozeRef}
        open={snoozeOpen}
        onClose={() => setSnoozeOpen(false)}
        align="end"
        onPick={(iso, human) => handlers.onSnooze(s.id, iso, human)}
      />
    </li>
  )
}

export function LabelChip({ name, bg, fg }: { name: string; bg: string; fg: string }) {
  return (
    <span
      style={{ backgroundColor: bg, color: fg }}
      className="inline-block max-w-[8rem] shrink-0 truncate rounded px-1.5 py-px text-[11px] font-medium leading-4"
    >
      {name}
    </span>
  )
}

export const ThreadRow = memo(ThreadRowImpl)

input.content:
import { useMemo, useRef, useState } from 'react'
import {
  Archive,
  ArchiveRestore,
  Ban,
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  Clock,
  EllipsisVertical,
  FolderInput,
  Inbox,
  Mail,
  MailOpen,
  RefreshCw,
  ShieldOff,
  Tag,
  Trash2,
  VolumeX,
} from 'lucide-react'
import { useMailActions } from '@/hooks/use-mail-actions'
import type { ListResult, ThreadSummary } from '@/lib/selectors'
import { SYSTEM, type Draft } from '@/lib/types'
import { cn, formatListDate, htmlToText, pluralize, truncate } from '@/lib/utils'
import { CATEGORIES, VIEWS } from '@/lib/views'
import { useMail } from '@/store/mail-store'
import type { Route } from '@/store/router'
import { DENSITY_ROW, useSettings } from '@/store/settings'
import { Checkbox, IconButton } from './ui/bits'
import { Menu, type MenuEntry } from './ui/popover'
import { Highlight } from './highlight'
import { LabelMenu } from './label-menu'
import { SnoozeMenu } from './snooze-menu'
import { ThreadRow, type RowHandlers } from './thread-row'

interface ListPaneProps {
  route: Route
  navigate: (r: Route) => void
  list: ListResult
  terms: string[]
  now: number
  selection: string[]
  onSelectionChange: (ids: string[]) => void
  cursor: number
  onCursorChange: (i: number) => void
  page: number
  onPageChange: (p: number) => void
  handlers: RowHandlers
  onOpenDraft: (id: string) => void
  onRefresh: () => void
  refreshing: boolean
  listRef: React.RefObject<HTMLDivElement | null>
  /** Narrow layout used beside the reading pane. */
  narrow?: boolean
}

export function ListPane({
  route,
  navigate,
  list,
  terms,
  now,
  selection,
  onSelectionChange,
  cursor,
  onCursorChange,
  page,
  onPageChange,
  handlers,
  onOpenDraft,
  onRefresh,
  refreshing,
  listRef,
  narrow,
}: ListPaneProps) {
  const { data } = useMail()
  const { settings } = useSettings()
  const actions = useMailActions()

  const pageSize = settings.pageSize
  const total = list.threads.length + list.drafts.length
  const start = page * pageSize

  const merged = useMemo(() => {
    const rows: ({ kind: 'thread'; item: ThreadSummary } | { kind: 'draft'; item: Draft })[] = [
      ...list.threads.map((t) => ({ kind: 'thread' as const, item: t })),
      ...list.drafts.map((d) => ({ kind: 'draft' as const, item: d })),
    ]
    if (list.drafts.length && list.threads.length) {
      rows.sort((a, b) => {
        const ad = a.kind === 'thread' ? a.item.date : a.item.updatedAt
        const bd = b.kind === 'thread' ? b.item.date : b.item.updatedAt
        return Date.parse(bd) - Date.parse(ad)
      })
    }
    return rows.slice(start, start + pageSize)
  }, [list.threads, list.drafts, start, pageSize])

  const pageThreadIds = merged.filter((r) => r.kind === 'thread').map((r) => r.item.id)
  const selected = new Set(selection)
  const allSelected = pageThreadIds.length > 0 && pageThreadIds.every((id) => selected.has(id))
  const someSelected = selection.length > 0

  const lastClicked = useRef<string | null>(null)

  const onSelect = (id: string, next: boolean, shift: boolean) => {
    if (shift && lastClicked.current) {
      const a = pageThreadIds.indexOf(lastClicked.current)
      const b = pageThreadIds.indexOf(id)
      if (a !== -1 && b !== -1) {
        const range = pageThreadIds.slice(Math.min(a, b), Math.max(a, b) + 1)
        const set = new Set(selection)
        range.forEach((r) => (next ? set.add(r) : set.delete(r)))
        onSelectionChange([...set])
        lastClicked.current = id
        return
      }
    }
    const set = new Set(selection)
    if (next) set.add(id)
    else set.delete(id)
    lastClicked.current = id
    onSelectionChange([...set])
  }

  const rowHandlers: RowHandlers = { ...handlers, onSelect }

  const emptyView = VIEWS[route.view]
  const showTabs =
    settings.showCategoryTabs &&
    route.view === 'inbox' &&
    !route.search &&
    !route.labelId &&
    !narrow

  return (
    <div className="flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden rounded-none bg-surface sm:rounded-2xl">
      <ListToolbar
        route={route}
        navigate={navigate}
        selection={selection}
        onSelectionChange={onSelectionChange}
        pageThreadIds={pageThreadIds}
        allSelected={allSelected}
        someSelected={someSelected}
        onRefresh={onRefresh}
        refreshing={refreshing}
        total={total}
        start={start}
        pageSize={pageSize}
        page={page}
        onPageChange={onPageChange}
        narrow={narrow}
        listThreadIds={list.threads.map((t) => t.id)}
      />

      {showTabs && <CategoryTabs route={route} navigate={navigate} />}

      {selection.length > 0 && selection.length === pageThreadIds.length && total > pageSize && (
        <div className="bg-accent-soft px-4 py-2 text-center text-[13px] text-accent-ink">
          All {pluralize(selection.length, 'conversation')} on this page are selected.{' '}
          <button
            type="button"
            className="font-medium underline"
            onClick={() => onSelectionChange(list.threads.map((t) => t.id))}
          >
            Select all {total} conversations
          </button>
        </div>
      )}

      <div ref={listRef} className="min-h-0 flex-1 overflow-y-auto scrollbar-thin">
        {merged.length === 0 ? (
          <EmptyState
            title={
              route.search
                ? 'No messages matched your search'
                : route.labelId
                  ? 'No conversations with this label'
                  : emptyView.emptyTitle
            }
            subtitle={
              route.search
                ? 'Try different keywords, or remove some search operators.'
                : route.labelId
                  ? 'Apply this label to a conversation and it will show up here.'
                  : emptyView.emptySubtitle
            }
          />
        ) : (
          <ul>
            {merged.map((row, i) =>
              row.kind === 'thread' ? (
                <ThreadRow
                  key={row.item.id}
                  summary={row.item}
                  selected={selected.has(row.item.id)}
                  cursor={cursor === i}
                  view={route.view}
                  density={settings.density}
                  terms={terms}
                  now={now}
                  showPreview={settings.previewText && !narrow}
                  hoverActions={settings.hoverActions && !narrow}
                  handlers={rowHandlers}
                />
              ) : (
                <DraftRow
                  key={row.item.id}
                  draft={row.item}
                  cursor={cursor === i}
                  terms={terms}
                  now={now}
                  onOpen={() => onOpenDraft(row.item.id)}
                  onDiscard={() => actions.discardDraft(row.item.id)}
                />
              ),
            )}
          </ul>
        )}

        {merged.length > 0 && (
          <footer className="px-4 py-6 text-center text-[12px] text-ink-4">
            {route.view === 'trash'
              ? 'Messages that have been in Trash more than 30 days will be automatically deleted.'
              : route.view === 'spam'
                ? 'Messages that have been in Spam more than 30 days will be automatically deleted.'
                : `${data.account.name} · ${data.account.email}`}
          </footer>
        )}
      </div>
    </div>
  )
}

/* -------------------------------------------------------------------------- */
/*  Toolbar                                                                    */
/* -------------------------------------------------------------------------- */

interface ToolbarProps {
  route: Route
  navigate: (r: Route) => void
  selection: string[]
  onSelectionChange: (ids: string[]) => void
  pageThreadIds: string[]
  listThreadIds: string[]
  allSelected: boolean
  someSelected: boolean
  onRefresh: () => void
  refreshing: boolean
  total: number
  start: number
  pageSize: number
  page: number
  onPageChange: (p: number) => void
  narrow?: boolean
}

function ListToolbar({
  route,
  navigate,
  selection,
  onSelectionChange,
  pageThreadIds,
  listThreadIds,
  allSelected,
  someSelected,
  onRefresh,
  refreshing,
  total,
  start,
  pageSize,
  page,
  onPageChange,
  narrow,
}: ToolbarProps) {
  const { data } = useMail()
  const actions = useMailActions()
  const selectRef = useRef<HTMLButtonElement>(null)
  const moreRef = useRef<HTMLButtonElement>(null)
  const moveRef = useRef<HTMLButtonElement>(null)
  const labelRef = useRef<HTMLButtonElement>(null)
  const snoozeRef = useRef<HTMLButtonElement>(null)
  const [open, setOpen] = useState<'select' | 'more' | 'move' | 'label' | 'snooze' | null>(null)
  const close = () => setOpen(null)

  const inTrash = route.view === 'trash'
  const inSpam = route.view === 'spam'
  const anyUnread = selection.some((id) =>
    data.threads[id]?.messageIds.some((m) => data.messages[m] && !data.messages[m].read),
  )

  const clear = () => onSelectionChange([])
  const run = (fn: () => void) => {
    fn()
    clear()
  }

  const pickBy = (test: (id: string) => boolean) =>
    onSelectionChange(pageThreadIds.filter(test))

  const isUnread = (id: string) =>
    Boolean(data.threads[id]?.messageIds.some((m) => data.messages[m] && !data.messages[m].read))
  const isStarred = (id: string) =>
    Boolean(data.threads[id]?.messageIds.some((m) => data.messages[m]?.starred))

  const moreEntries: MenuEntry[] = someSelected
    ? [
        {
          id: 'unread',
          label: 'Mark as unread',
          icon: <Mail />,
          onSelect: () => run(() => actions.setRead(selection, false)),
        },
        {
          id: 'read',
          label: 'Mark as read',
          icon: <MailOpen />,
          onSelect: () => run(() => actions.setRead(selection, true)),
        },
        { type: 'separator', id: 's1' },
        {
          id: 'important',
          label: 'Mark as important',
          onSelect: () => run(() => actions.setImportant(selection, true)),
        },
        {
          id: 'notimportant',
          label: 'Mark as not important',
          onSelect: () => run(() => actions.setImportant(selection, false)),
        },
        {
          id: 'star',
          label: 'Add star',
          onSelect: () => run(() => actions.setStarred(selection, true)),
        },
        {
          id: 'unstar',
          label: 'Remove star',
          onSelect: () => run(() => actions.setStarred(selection, false)),
        },
        { type: 'separator', id: 's2' },
        {
          id: 'mute',
          label: 'Mute',
          icon: <VolumeX />,
          onSelect: () => run(() => actions.setMuted(selection, true)),
        },
        ...(inSpam
          ? [
              {
                id: 'notspam',
                label: 'Not spam',
                icon: <ShieldOff />,
                onSelect: () => run(() => actions.notSpam(selection)),
              } as MenuEntry,
            ]
          : []),
        ...(inTrash
          ? [
              {
                id: 'forever',
                label: 'Delete forever',
                icon: <Trash2 />,
                danger: true,
                onSelect: () => run(() => actions.deleteForever(selection)),
              } as MenuEntry,
            ]
          : []),
      ]
    : [
        {
          id: 'markall',
          label: 'Mark all as read',
          icon: <MailOpen />,
          disabled: !listThreadIds.length,
          onSelect: () => actions.setRead(listThreadIds, true),
        },
        {
          id: 'selectall',
          label: 'Select all conversations',
          disabled: !listThreadIds.length,
          onSelect: () => onSelectionChange(listThreadIds),
        },
        ...(inTrash || inSpam
          ? [
              { type: 'separator', id: 's3' } as MenuEntry,
              {
                id: 'empty',
                label: inTrash ? 'Empty Trash now' : 'Delete all spam now',
                icon: <Trash2 />,
                danger: true,
                disabled: !listThreadIds.length,
                onSelect: () =>
                  actions.emptyFolder(inTrash ? SYSTEM.trash : SYSTEM.spam, inTrash ? 'Trash' : 'Spam'),
              } as MenuEntry,
            ]
          : []),
      ]

  return (
    <div className="flex h-12 shrink-0 items-center gap-0.5 px-1 sm:px-2">
      <div className="flex items-center">
        <Checkbox
          checked={allSelected}
          indeterminate={someSelected && !allSelected}
          label="Select all conversations on this page"
          stopPropagation={false}
          onChange={(next) => onSelectionChange(next ? pageThreadIds : [])}
        />
        <button
          ref={selectRef}
          type="button"
          aria-label="Selection options"
          onClick={() => setOpen(open === 'select' ? null : 'select')}
          className="-ml-1.5 flex h-8 w-5 items-center justify-center rounded text-ink-3 hover:text-ink"
        >
          <ChevronDown className="h-4 w-4" />
        </button>
      </div>

      {someSelected ? (
        <div className="flex min-w-0 items-center gap-0.5">
          {inTrash ? (
            <IconButton label="Move to inbox" onClick={() => run(() => actions.untrash(selection))}>
              <ArchiveRestore />
            </IconButton>
          ) : (
            <IconButton
              label="Archive"
              shortcut="E"
              onClick={() => run(() => actions.archive(selection))}
            >
              <Archive />
            </IconButton>
          )}
          {!inSpam && (
            <IconButton label="Report spam" onClick={() => run(() => actions.markSpam(selection))}>
              <Ban />
            </IconButton>
          )}
          <IconButton
            label={inTrash ? 'Delete forever' : 'Delete'}
            shortcut="#"
            onClick={() => run(() => (inTrash ? actions.deleteForever(selection) : actions.trash(selection)))}
          >
            <Trash2 />
          </IconButton>
          <span className="mx-1 hidden h-5 w-px bg-line sm:block" />
          <IconButton
            label={anyUnread ? 'Mark as read' : 'Mark as unread'}
            className="hidden sm:inline-flex"
            onClick={() => run(() => actions.setRead(selection, anyUnread))}
          >
            {anyUnread ? <MailOpen /> : <Mail />}
          </IconButton>
          <IconButton
            ref={snoozeRef}
            label="Snooze"
            className="hidden sm:inline-flex"
            active={open === 'snooze'}
            onClick={() => setOpen(open === 'snooze' ? null : 'snooze')}
          >
            <Clock />
          </IconButton>
          <span className="mx-1 hidden h-5 w-px bg-line md:block" />
          <IconButton
            ref={moveRef}
            label="Move to"
            className="hidden md:inline-flex"
            active={open === 'move'}
            onClick={() => setOpen(open === 'move' ? null : 'move')}
          >
            <FolderInput />
          </IconButton>
          <IconButton
            ref={labelRef}
            label="Labels"
            className="hidden md:inline-flex"
            active={open === 'label'}
            onClick={() => setOpen(open === 'label' ? null : 'label')}
          >
            <Tag />
          </IconButton>
        </div>
      ) : (
        <IconButton label="Refresh" shortcut="R" onClick={onRefresh}>
          <RefreshCw className={refreshing ? 'animate-spin' : undefined} />
        </IconButton>
      )}

      <IconButton
        ref={moreRef}
        label="More"
        active={open === 'more'}
        onClick={() => setOpen(open === 'more' ? null : 'more')}
      >
        <EllipsisVertical />
      </IconButton>

      <div className="ml-auto flex items-center gap-0.5">
        {someSelected ? (
          <span className="px-2 text-[13px] text-ink-2">
            {pluralize(selection.length, 'selected')}
          </span>
        ) : (
          !narrow && (
            <span className="hidden px-2 text-[12px] tabular-nums text-ink-3 sm:block">
              {total === 0 ? '0' : `${start + 1}–${Math.min(total, start + pageSize)}`} of {total}
            </span>
          )
        )}
        <IconButton
          label="Newer"
          disabled={page === 0}
          onClick={() => onPageChange(page - 1)}
          size="sm"
        >
          <ChevronLeft />
        </IconButton>
        <IconButton
          label="Older"
          disabled={start + pageSize >= total}
          onClick={() => onPageChange(page + 1)}
          size="sm"
        >
          <ChevronRight />
        </IconButton>
      </div>

      <Menu
        anchorRef={selectRef}
        open={open === 'select'}
        onClose={close}
        ariaLabel="Select"
        entries={[
          { id: 'all', label: 'All', onSelect: () => onSelectionChange(pageThreadIds) },
          { id: 'none', label: 'None', onSelect: () => onSelectionChange([]) },
          { id: 'read', label: 'Read', onSelect: () => pickBy((id) => !isUnread(id)) },
          { id: 'unread', label: 'Unread', onSelect: () => pickBy(isUnread) },
          { id: 'starred', label: 'Starred', onSelect: () => pickBy(isStarred) },
          { id: 'unstarred', label: 'Unstarred', onSelect: () => pickBy((id) => !isStarred(id)) },
        ]}
      />
      <Menu
        anchorRef={moreRef}
        open={open === 'more'}
        onClose={close}
        ariaLabel="More actions"
        entries={moreEntries}
      />
      <Menu
        anchorRef={moveRef}
        open={open === 'move'}
        onClose={close}
        ariaLabel="Move to"
        entries={[
          { type: 'header', id: 'h', label: 'Move to' },
          {
            id: 'inbox',
            label: 'Inbox',
            icon: <Inbox />,
            onSelect: () => run(() => actions.moveToInbox(selection)),
          },
          {
            id: 'spam',
            label: 'Spam',
            icon: <Ban />,
            onSelect: () => run(() => actions.markSpam(selection)),
          },
          {
            id: 'trash',
            label: 'Trash',
            icon: <Trash2 />,
            onSelect: () => run(() => actions.trash(selection)),
          },
          { type: 'separator', id: 's' },
          {
            id: 'archive',
            label: 'Archive (remove from Inbox)',
            icon: <Archive />,
            onSelect: () => run(() => actions.archive(selection)),
          },
        ]}
      />
      <LabelMenu
        anchorRef={labelRef}
        open={open === 'label'}
        onClose={close}
        threadIds={selection}
      />
      <SnoozeMenu
        anchorRef={snoozeRef}
        open={open === 'snooze'}
        onClose={close}
        onPick={(iso, human) => run(() => actions.snooze(selection, iso, human))}
      />
      {route.settingsTab === undefined && navigate === undefined && null}
    </div>
  )
}

/* -------------------------------------------------------------------------- */
/*  Category tabs                                                              */
/* -------------------------------------------------------------------------- */

function CategoryTabs({ route, navigate }: { route: Route; navigate: (r: Route) => void }) {
  const active = route.category ?? 'primary'
  return (
    <div className="flex shrink-0 overflow-x-auto no-scrollbar border-b border-line-soft">
      {CATEGORIES.map((c) => {
        const on = active === c.id
        const Icon = c.icon
        return (
          <button
            key={c.id}
            type="button"
            onClick={() => navigate({ view: 'inbox', category: c.id === 'primary' ? undefined : c.id })}
            className={cn(
              'relative flex min-w-[7rem] flex-1 items-center gap-3 px-4 py-3 text-[13px] font-medium transition-colors sm:min-w-[9rem]',
              on ? 'text-ink' : 'text-ink-3 hover:bg-surface-2 hover:text-ink-2',
            )}
          >
            <Icon className="h-5 w-5 shrink-0" style={{ color: on ? c.accent : undefined }} />
            <span className="truncate">{c.title}</span>
            {on && (
              <span
                className="absolute inset-x-0 bottom-0 h-[3px] rounded-t"
                style={{ backgroundColor: c.accent }}
              />
            )}
          </button>
        )
      })}
    </div>
  )
}

/* -------------------------------------------------------------------------- */
/*  Draft row & empty state                                                    */
/* -------------------------------------------------------------------------- */

function DraftRow({
  draft,
  cursor,
  terms,
  now,
  onOpen,
  onDiscard,
}: {
  draft: Draft
  cursor: boolean
  terms: string[]
  now: number
  onOpen: () => void
  onDiscard: () => void
}) {
  const { settings } = useSettings()
  const recipients = draft.to.map((a) => a.name || a.email).join(', ')
  const snippet = truncate(htmlToText(draft.bodyHtml), 200)

  return (
    <li
      className={cn(
        'group relative border-b border-line-soft/70 bg-read transition-colors hover:z-[1] hover:shadow-row',
        cursor && 'ring-1 ring-inset ring-accent/45',
      )}
    >
      <div
        role="button"
        tabIndex={-1}
        onClick={onOpen}
        className={cn(
          'flex cursor-pointer items-center gap-1 pl-2 pr-3 sm:pl-[6.25rem]',
          DENSITY_ROW[settings.density],
        )}
      >
        <span className="min-w-0 flex-1 truncate text-[14px]">
          <span className="mr-2 text-danger">Draft</span>
          <span className="text-ink">
            <Highlight text={draft.subject || '(no subject)'} terms={terms} />
          </span>
          <span className="text-ink-3">
            {recipients && ` — to ${recipients}`}
            {snippet && ` — ${snippet}`}
          </span>
        </span>
        <div className="relative flex w-[7rem] shrink-0 items-center justify-end self-stretch">
          <span className="text-[12px] text-ink-3 group-hover:invisible">
            {formatListDate(draft.updatedAt, new Date(now))}
          </span>
          <div
            className="absolute inset-y-0 right-0 hidden items-center group-hover:flex"
            onClick={(e) => e.stopPropagation()}
          >
            <IconButton label="Discard draft" size="sm" onClick={onDiscard}>
              <Trash2 />
            </IconButton>
          </div>
        </div>
      </div>
    </li>
  )
}

function EmptyState({ title, subtitle }: { title: string; subtitle: string }) {
  return (
    <div className="flex flex-col items-center justify-center gap-2 px-8 py-24 text-center">
      <div className="mb-2 flex h-16 w-16 items-center justify-center rounded-full bg-surface-2 text-ink-3">
        <Inbox className="h-7 w-7" />
      </div>
      <p className="text-[15px] font-medium text-ink">{title}</p>
      <p className="max-w-sm text-[13px] text-ink-3">{subtitle}</p>
    </div>
  )
}

tool_use_result.content:
import { useMemo, useRef, useState } from 'react'
import {
  Archive,
  ArchiveRestore,
  Ban,
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  Clock,
  EllipsisVertical,
  FolderInput,
  Inbox,
  Mail,
  MailOpen,
  RefreshCw,
  ShieldOff,
  Tag,
  Trash2,
  VolumeX,
} from 'lucide-react'
import { useMailActions } from '@/hooks/use-mail-actions'
import type { ListResult, ThreadSummary } from '@/lib/selectors'
import { SYSTEM, type Draft } from '@/lib/types'
import { cn, formatListDate, htmlToText, pluralize, truncate } from '@/lib/utils'
import { CATEGORIES, VIEWS } from '@/lib/views'
import { useMail } from '@/store/mail-store'
import type { Route } from '@/store/router'
import { DENSITY_ROW, useSettings } from '@/store/settings'
import { Checkbox, IconButton } from './ui/bits'
import { Menu, type MenuEntry } from './ui/popover'
import { Highlight } from './highlight'
import { LabelMenu } from './label-menu'
import { SnoozeMenu } from './snooze-menu'
import { ThreadRow, type RowHandlers } from './thread-row'

interface ListPaneProps {
  route: Route
  navigate: (r: Route) => void
  list: ListResult
  terms: string[]
  now: number
  selection: string[]
  onSelectionChange: (ids: string[]) => void
  cursor: number
  onCursorChange: (i: number) => void
  page: number
  onPageChange: (p: number) => void
  handlers: RowHandlers
  onOpenDraft: (id: string) => void
  onRefresh: () => void
  refreshing: boolean
  listRef: React.RefObject<HTMLDivElement | null>
  /** Narrow layout used beside the reading pane. */
  narrow?: boolean
}

export function ListPane({
  route,
  navigate,
  list,
  terms,
  now,
  selection,
  onSelectionChange,
  cursor,
  onCursorChange,
  page,
  onPageChange,
  handlers,
  onOpenDraft,
  onRefresh,
  refreshing,
  listRef,
  narrow,
}: ListPaneProps) {
  const { data } = useMail()
  const { settings } = useSettings()
  const actions = useMailActions()

  const pageSize = settings.pageSize
  const total = list.threads.length + list.drafts.length
  const start = page * pageSize

  const merged = useMemo(() => {
    const rows: ({ kind: 'thread'; item: ThreadSummary } | { kind: 'draft'; item: Draft })[] = [
      ...list.threads.map((t) => ({ kind: 'thread' as const, item: t })),
      ...list.drafts.map((d) => ({ kind: 'draft' as const, item: d })),
    ]
    if (list.drafts.length && list.threads.length) {
      rows.sort((a, b) => {
        const ad = a.kind === 'thread' ? a.item.date : a.item.updatedAt
        const bd = b.kind === 'thread' ? b.item.date : b.item.updatedAt
        return Date.parse(bd) - Date.parse(ad)
      })
    }
    return rows.slice(start, start + pageSize)
  }, [list.threads, list.drafts, start, pageSize])

  const pageThreadIds = merged.filter((r) => r.kind === 'thread').map((r) => r.item.id)
  const selected = new Set(selection)
  const allSelected = pageThreadIds.length > 0 && pageThreadIds.every((id) => selected.has(id))
  const someSelected = selection.length > 0

  const lastClicked = useRef<string | null>(null)

  const onSelect = (id: string, next: boolean, shift: boolean) => {
    if (shift && lastClicked.current) {
      const a = pageThreadIds.indexOf(lastClicked.current)
      const b = pageThreadIds.indexOf(id)
      if (a !== -1 && b !== -1) {
        const range = pageThreadIds.slice(Math.min(a, b), Math.max(a, b) + 1)
        const set = new Set(selection)
        range.forEach((r) => (next ? set.add(r) : set.delete(r)))
        onSelectionChange([...set])
        lastClicked.current = id
        return
      }
    }
    const set = new Set(selection)
    if (next) set.add(id)
    else set.delete(id)
    lastClicked.current = id
    onSelectionChange([...set])
  }

  const rowHandlers: RowHandlers = { ...handlers, onSelect }

  const emptyView = VIEWS[route.view]
  const showTabs =
    settings.showCategoryTabs &&
    route.view === 'inbox' &&
    !route.search &&
    !route.labelId &&
    !narrow

  return (
    <div className="flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden rounded-none bg-surface sm:rounded-2xl">
      <ListToolbar
        route={route}
        navigate={navigate}
        selection={selection}
        onSelectionChange={onSelectionChange}
        pageThreadIds={pageThreadIds}
        allSelected={allSelected}
        someSelected={someSelected}
        onRefresh={onRefresh}
        refreshing={refreshing}
        total={total}
        start={start}
        pageSize={pageSize}
        page={page}
        onPageChange={onPageChange}
        narrow={narrow}
        listThreadIds={list.threads.map((t) => t.id)}
      />

      {showTabs && <CategoryTabs route={route} navigate={navigate} />}

      {selection.length > 0 && selection.length === pageThreadIds.length && total > pageSize && (
        <div className="bg-accent-soft px-4 py-2 text-center text-[13px] text-accent-ink">
          All {pluralize(selection.length, 'conversation')} on this page are selected.{' '}
          <button
            type="button"
            className="font-medium underline"
            onClick={() => onSelectionChange(list.threads.map((t) => t.id))}
          >
            Select all {total} conversations
          </button>
        </div>
      )}

      <div ref={listRef} className="min-h-0 flex-1 overflow-y-auto scrollbar-thin">
        {merged.length === 0 ? (
          <EmptyState
            title={
              route.search
                ? 'No messages matched your search'
                : route.labelId
                  ? 'No conversations with this label'
                  : emptyView.emptyTitle
            }
            subtitle={
              route.search
                ? 'Try different keywords, or remove some search operators.'
                : route.labelId
                  ? 'Apply this label to a conversation and it will show up here.'
                  : emptyView.emptySubtitle
            }
          />
        ) : (
          <ul>
            {merged.map((row, i) =>
              row.kind === 'thread' ? (
                <ThreadRow
                  key={row.item.id}
                  summary={row.item}
                  selected={selected.has(row.item.id)}
                  cursor={cursor === i}
                  view={route.view}
                  density={settings.density}
                  terms={terms}
                  now={now}
                  showPreview={settings.previewText && !narrow}
                  hoverActions={settings.hoverActions && !narrow}
                  handlers={rowHandlers}
                />
              ) : (
                <DraftRow
                  key={row.item.id}
                  draft={row.item}
                  cursor={cursor === i}
                  terms={terms}
                  now={now}
                  onOpen={() => onOpenDraft(row.item.id)}
                  onDiscard={() => actions.discardDraft(row.item.id)}
                />
              ),
            )}
          </ul>
        )}

        {merged.length > 0 && (
          <footer className="px-4 py-6 text-center text-[12px] text-ink-4">
            {route.view === 'trash'
              ? 'Messages that have been in Trash more than 30 days will be automatically deleted.'
              : route.view === 'spam'
                ? 'Messages that have been in Spam more than 30 days will be automatically deleted.'
                : `${data.account.name} · ${data.account.email}`}
          </footer>
        )}
      </div>
    </div>
  )
}

/* -------------------------------------------------------------------------- */
/*  Toolbar                                                                    */
/* -------------------------------------------------------------------------- */

interface ToolbarProps {
  route: Route
  navigate: (r: Route) => void
  selection: string[]
  onSelectionChange: (ids: string[]) => void
  pageThreadIds: string[]
  listThreadIds: string[]
  allSelected: boolean
  someSelected: boolean
  onRefresh: () => void
  refreshing: boolean
  total: number
  start: number
  pageSize: number
  page: number
  onPageChange: (p: number) => void
  narrow?: boolean
}

function ListToolbar({
  route,
  navigate,
  selection,
  onSelectionChange,
  pageThreadIds,
  listThreadIds,
  allSelected,
  someSelected,
  onRefresh,
  refreshing,
  total,
  start,
  pageSize,
  page,
  onPageChange,
  narrow,
}: ToolbarProps) {
  const { data } = useMail()
  const actions = useMailActions()
  const selectRef = useRef<HTMLButtonElement>(null)
  const moreRef = useRef<HTMLButtonElement>(null)
  const moveRef = useRef<HTMLButtonElement>(null)
  const labelRef = useRef<HTMLButtonElement>(null)
  const snoozeRef = useRef<HTMLButtonElement>(null)
  const [open, setOpen] = useState<'select' | 'more' | 'move' | 'label' | 'snooze' | null>(null)
  const close = () => setOpen(null)

  const inTrash = route.view === 'trash'
  const inSpam = route.view === 'spam'
  const anyUnread = selection.some((id) =>
    data.threads[id]?.messageIds.some((m) => data.messages[m] && !data.messages[m].read),
  )

  const clear = () => onSelectionChange([])
  const run = (fn: () => void) => {
    fn()
    clear()
  }

  const pickBy = (test: (id: string) => boolean) =>
    onSelectionChange(pageThreadIds.filter(test))

  const isUnread = (id: string) =>
    Boolean(data.threads[id]?.messageIds.some((m) => data.messages[m] && !data.messages[m].read))
  const isStarred = (id: string) =>
    Boolean(data.threads[id]?.messageIds.some((m) => data.messages[m]?.starred))

  const moreEntries: MenuEntry[] = someSelected
    ? [
        {
          id: 'unread',
          label: 'Mark as unread',
          icon: <Mail />,
          onSelect: () => run(() => actions.setRead(selection, false)),
        },
        {
          id: 'read',
          label: 'Mark as read',
          icon: <MailOpen />,
          onSelect: () => run(() => actions.setRead(selection, true)),
        },
        { type: 'separator', id: 's1' },
        {
          id: 'important',
          label: 'Mark as important',
          onSelect: () => run(() => actions.setImportant(selection, true)),
        },
        {
          id: 'notimportant',
          label: 'Mark as not important',
          onSelect: () => run(() => actions.setImportant(selection, false)),
        },
        {
          id: 'star',
          label: 'Add star',
          onSelect: () => run(() => actions.setStarred(selection, true)),
        },
        {
          id: 'unstar',
          label: 'Remove star',
          onSelect: () => run(() => actions.setStarred(selection, false)),
        },
        { type: 'separator', id: 's2' },
        {
          id: 'mute',
          label: 'Mute',
          icon: <VolumeX />,
          onSelect: () => run(() => actions.setMuted(selection, true)),
        },
        ...(inSpam
          ? [
              {
                id: 'notspam',
                label: 'Not spam',
                icon: <ShieldOff />,
                onSelect: () => run(() => actions.notSpam(selection)),
              } as MenuEntry,
            ]
          : []),
        ...(inTrash
          ? [
              {
                id: 'forever',
                label: 'Delete forever',
                icon: <Trash2 />,
                danger: true,
                onSelect: () => run(() => actions.deleteForever(selection)),
              } as MenuEntry,
            ]
          : []),
      ]
    : [
        {
          id: 'markall',
          label: 'Mark all as read',
          icon: <MailOpen />,
          disabled: !listThreadIds.length,
          onSelect: () => actions.setRead(listThreadIds, true),
        },
        {
          id: 'selectall',
          label: 'Select all conversations',
          disabled: !listThreadIds.length,
          onSelect: () => onSelectionChange(listThreadIds),
        },
        ...(inTrash || inSpam
          ? [
              { type: 'separator', id: 's3' } as MenuEntry,
              {
                id: 'empty',
                label: inTrash ? 'Empty Trash now' : 'Delete all spam now',
                icon: <Trash2 />,
                danger: true,
                disabled: !listThreadIds.length,
                onSelect: () =>
                  actions.emptyFolder(inTrash ? SYSTEM.trash : SYSTEM.spam, inTrash ? 'Trash' : 'Spam'),
              } as MenuEntry,
            ]
          : []),
      ]

  return (
    <div className="flex h-12 shrink-0 items-center gap-0.5 px-1 sm:px-2">
      <div className="flex items-center">
        <Checkbox
          checked={allSelected}
          indeterminate={someSelected && !allSelected}
          label="Select all conversations on this page"
          stopPropagation={false}
          onChange={(next) => onSelectionChange(next ? pageThreadIds : [])}
        />
        <button
          ref={selectRef}
          type="button"
          aria-label="Selection options"
          onClick={() => setOpen(open === 'select' ? null : 'select')}
          className="-ml-1.5 flex h-8 w-5 items-center justify-center rounded text-ink-3 hover:text-ink"
        >
          <ChevronDown className="h-4 w-4" />
        </button>
      </div>

      {someSelected ? (
        <div className="flex min-w-0 items-center gap-0.5">
          {inTrash ? (
            <IconButton label="Move to inbox" onClick={() => run(() => actions.untrash(selection))}>
              <ArchiveRestore />
            </IconButton>
          ) : (
            <IconButton
              label="Archive"
              shortcut="E"
              onClick={() => run(() => actions.archive(selection))}
            >
              <Archive />
            </IconButton>
          )}
          {!inSpam && (
            <IconButton label="Report spam" onClick={() => run(() => actions.markSpam(selection))}>
              <Ban />
            </IconButton>
          )}
          <IconButton
            label={inTrash ? 'Delete forever' : 'Delete'}
            shortcut="#"
            onClick={() => run(() => (inTrash ? actions.deleteForever(selection) : actions.trash(selection)))}
          >
            <Trash2 />
          </IconButton>
          <span className="mx-1 hidden h-5 w-px bg-line sm:block" />
          <IconButton
            label={anyUnread ? 'Mark as read' : 'Mark as unread'}
            className="hidden sm:inline-flex"
            onClick={() => run(() => actions.setRead(selection, anyUnread))}
          >
            {anyUnread ? <MailOpen /> : <Mail />}
          </IconButton>
          <IconButton
            ref={snoozeRef}
            label="Snooze"
            className="hidden sm:inline-flex"
            active={open === 'snooze'}
            onClick={() => setOpen(open === 'snooze' ? null : 'snooze')}
          >
            <Clock />
          </IconButton>
          <span className="mx-1 hidden h-5 w-px bg-line md:block" />
          <IconButton
            ref={moveRef}
            label="Move to"
            className="hidden md:inline-flex"
            active={open === 'move'}
            onClick={() => setOpen(open === 'move' ? null : 'move')}
          >
            <FolderInput />
          </IconButton>
          <IconButton
            ref={labelRef}
            label="Labels"
            className="hidden md:inline-flex"
            active={open === 'label'}
            onClick={() => setOpen(open === 'label' ? null : 'label')}
          >
            <Tag />
          </IconButton>
        </div>
      ) : (
        <IconButton label="Refresh" shortcut="R" onClick={onRefresh}>
          <RefreshCw className={refreshing ? 'animate-spin' : undefined} />
        </IconButton>
      )}

      <IconButton
        ref={moreRef}
        label="More"
        active={open === 'more'}
        onClick={() => setOpen(open === 'more' ? null : 'more')}
      >
        <EllipsisVertical />
      </IconButton>

      <div className="ml-auto flex items-center gap-0.5">
        {someSelected ? (
          <span className="px-2 text-[13px] text-ink-2">
            {pluralize(selection.length, 'selected')}
          </span>
        ) : (
          !narrow && (
            <span className="hidden px-2 text-[12px] tabular-nums text-ink-3 sm:block">
              {total === 0 ? '0' : `${start + 1}–${Math.min(total, start + pageSize)}`} of {total}
            </span>
          )
        )}
        <IconButton
          label="Newer"
          disabled={page === 0}
          onClick={() => onPageChange(page - 1)}
          size="sm"
        >
          <ChevronLeft />
        </IconButton>
        <IconButton
          label="Older"
          disabled={start + pageSize >= total}
          onClick={() => onPageChange(page + 1)}
          size="sm"
        >
          <ChevronRight />
        </IconButton>
      </div>

      <Menu
        anchorRef={selectRef}
        open={open === 'select'}
        onClose={close}
        ariaLabel="Select"
        entries={[
          { id: 'all', label: 'All', onSelect: () => onSelectionChange(pageThreadIds) },
          { id: 'none', label: 'None', onSelect: () => onSelectionChange([]) },
          { id: 'read', label: 'Read', onSelect: () => pickBy((id) => !isUnread(id)) },
          { id: 'unread', label: 'Unread', onSelect: () => pickBy(isUnread) },
          { id: 'starred', label: 'Starred', onSelect: () => pickBy(isStarred) },
          { id: 'unstarred', label: 'Unstarred', onSelect: () => pickBy((id) => !isStarred(id)) },
        ]}
      />
      <Menu
        anchorRef={moreRef}
        open={open === 'more'}
        onClose={close}
        ariaLabel="More actions"
        entries={moreEntries}
      />
      <Menu
        anchorRef={moveRef}
        open={open === 'move'}
        onClose={close}
        ariaLabel="Move to"
        entries={[
          { type: 'header', id: 'h', label: 'Move to' },
          {
            id: 'inbox',
            label: 'Inbox',
            icon: <Inbox />,
            onSelect: () => run(() => actions.moveToInbox(selection)),
          },
          {
            id: 'spam',
            label: 'Spam',
            icon: <Ban />,
            onSelect: () => run(() => actions.markSpam(selection)),
          },
          {
            id: 'trash',
            label: 'Trash',
            icon: <Trash2 />,
            onSelect: () => run(() => actions.trash(selection)),
          },
          { type: 'separator', id: 's' },
          {
            id: 'archive',
            label: 'Archive (remove from Inbox)',
            icon: <Archive />,
            onSelect: () => run(() => actions.archive(selection)),
          },
        ]}
      />
      <LabelMenu
        anchorRef={labelRef}
        open={open === 'label'}
        onClose={close}
        threadIds={selection}
      />
      <SnoozeMenu
        anchorRef={snoozeRef}
        open={open === 'snooze'}
        onClose={close}
        onPick={(iso, human) => run(() => actions.snooze(selection, iso, human))}
      />
      {route.settingsTab === undefined && navigate === undefined && null}
    </div>
  )
}

/* -------------------------------------------------------------------------- */
/*  Category tabs                                                              */
/* -------------------------------------------------------------------------- */

function CategoryTabs({ route, navigate }: { route: Route; navigate: (r: Route) => void }) {
  const active = route.category ?? 'primary'
  return (
    <div className="flex shrink-0 overflow-x-auto no-scrollbar border-b border-line-soft">
      {CATEGORIES.map((c) => {
        const on = active === c.id
        const Icon = c.icon
        return (
          <button
            key={c.id}
            type="button"
            onClick={() => navigate({ view: 'inbox', category: c.id === 'primary' ? undefined : c.id })}
            className={cn(
              'relative flex min-w-[7rem] flex-1 items-center gap-3 px-4 py-3 text-[13px] font-medium transition-colors sm:min-w-[9rem]',
              on ? 'text-ink' : 'text-ink-3 hover:bg-surface-2 hover:text-ink-2',
            )}
          >
            <Icon className="h-5 w-5 shrink-0" style={{ color: on ? c.accent : undefined }} />
            <span className="truncate">{c.title}</span>
            {on && (
              <span
                className="absolute inset-x-0 bottom-0 h-[3px] rounded-t"
                style={{ backgroundColor: c.accent }}
              />
            )}
          </button>
        )
      })}
    </div>
  )
}

/* -------------------------------------------------------------------------- */
/*  Draft row & empty state                                                    */
/* -------------------------------------------------------------------------- */

function DraftRow({
  draft,
  cursor,
  terms,
  now,
  onOpen,
  onDiscard,
}: {
  draft: Draft
  cursor: boolean
  terms: string[]
  now: number
  onOpen: () => void
  onDiscard: () => void
}) {
  const { settings } = useSettings()
  const recipients = draft.to.map((a) => a.name || a.email).join(', ')
  const snippet = truncate(htmlToText(draft.bodyHtml), 200)

  return (
    <li
      className={cn(
        'group relative border-b border-line-soft/70 bg-read transition-colors hover:z-[1] hover:shadow-row',
        cursor && 'ring-1 ring-inset ring-accent/45',
      )}
    >
      <div
        role="button"
        tabIndex={-1}
        onClick={onOpen}
        className={cn(
          'flex cursor-pointer items-center gap-1 pl-2 pr-3 sm:pl-[6.25rem]',
          DENSITY_ROW[settings.density],
        )}
      >
        <span className="min-w-0 flex-1 truncate text-[14px]">
          <span className="mr-2 text-danger">Draft</span>
          <span className="text-ink">
            <Highlight text={draft.subject || '(no subject)'} terms={terms} />
          </span>
          <span className="text-ink-3">
            {recipients && ` — to ${recipients}`}
            {snippet && ` — ${snippet}`}
          </span>
        </span>
        <div className="relative flex w-[7rem] shrink-0 items-center justify-end self-stretch">
          <span className="text-[12px] text-ink-3 group-hover:invisible">
            {formatListDate(draft.updatedAt, new Date(now))}
          </span>
          <div
            className="absolute inset-y-0 right-0 hidden items-center group-hover:flex"
            onClick={(e) => e.stopPropagation()}
          >
            <IconButton label="Discard draft" size="sm" onClick={onDiscard}>
              <Trash2 />
            </IconButton>
          </div>
        </div>
      </div>
    </li>
  )
}

function EmptyState({ title, subtitle }: { title: string; subtitle: string }) {
  return (
    <div className="flex flex-col items-center justify-center gap-2 px-8 py-24 text-center">
      <div className="mb-2 flex h-16 w-16 items-center justify-center rounded-full bg-surface-2 text-ink-3">
        <Inbox className="h-7 w-7" />
      </div>
      <p className="text-[15px] font-medium text-ink">{title}</p>
      <p className="max-w-sm text-[13px] text-ink-3">{subtitle}</p>
    </div>
  )
}

