tool_use_result.originalFile:
import { useMemo, useRef, useState } from 'react'
import {
  Archive,
  ArchiveRestore,
  Ban,
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  Clock,
  EllipsisVertical,
  FolderInput,
  Inbox,
  Mail,
  MailOpen,
  RefreshCw,
  ShieldOff,
  Tag,
  Trash2,
  VolumeX,
} from 'lucide-react'
import { useMailActions } from '@/hooks/use-mail-actions'
import type { ListResult, ThreadSummary } from '@/lib/selectors'
import { SYSTEM, type Draft } from '@/lib/types'
import { cn, formatListDate, htmlToText, pluralize, truncate } from '@/lib/utils'
import { CATEGORIES, VIEWS } from '@/lib/views'
import { useMail } from '@/store/mail-store'
import type { Route } from '@/store/router'
import { DENSITY_ROW, useSettings } from '@/store/settings'
import { Checkbox, IconButton } from './ui/bits'
import { Menu, type MenuEntry } from './ui/popover'
import { Highlight } from './highlight'
import { LabelMenu } from './label-menu'
import { SnoozeMenu } from './snooze-menu'
import { ThreadRow, type RowHandlers } from './thread-row'

interface ListPaneProps {
  route: Route
  navigate: (r: Route) => void
  list: ListResult
  terms: string[]
  now: number
  selection: string[]
  onSelectionChange: (ids: string[]) => void
  cursor: number
  onCursorChange: (i: number) => void
  page: number
  onPageChange: (p: number) => void
  handlers: RowHandlers
  onOpenDraft: (id: string) => void
  onRefresh: () => void
  refreshing: boolean
  listRef: React.RefObject<HTMLDivElement | null>
  /** Narrow layout used beside the reading pane. */
  narrow?: boolean
}

export function ListPane({
  route,
  navigate,
  list,
  terms,
  now,
  selection,
  onSelectionChange,
  cursor,
  onCursorChange,
  page,
  onPageChange,
  handlers,
  onOpenDraft,
  onRefresh,
  refreshing,
  listRef,
  narrow,
}: ListPaneProps) {
  const { data } = useMail()
  const { settings } = useSettings()
  const actions = useMailActions()

  const pageSize = settings.pageSize
  const total = list.threads.length + list.drafts.length
  const start = page * pageSize

  const merged = useMemo(() => {
    const rows: ({ kind: 'thread'; item: ThreadSummary } | { kind: 'draft'; item: Draft })[] = [
      ...list.threads.map((t) => ({ kind: 'thread' as const, item: t })),
      ...list.drafts.map((d) => ({ kind: 'draft' as const, item: d })),
    ]
    if (list.drafts.length && list.threads.length) {
      rows.sort((a, b) => {
        const ad = a.kind === 'thread' ? a.item.date : a.item.updatedAt
        const bd = b.kind === 'thread' ? b.item.date : b.item.updatedAt
        return Date.parse(bd) - Date.parse(ad)
      })
    }
    return rows.slice(start, start + pageSize)
  }, [list.threads, list.drafts, start, pageSize])

  const pageThreadIds = merged.filter((r) => r.kind === 'thread').map((r) => r.item.id)
  const selected = new Set(selection)
  const allSelected = pageThreadIds.length > 0 && pageThreadIds.every((id) => selected.has(id))
  const someSelected = selection.length > 0

  const lastClicked = useRef<string | null>(null)

  const onSelect = (id: string, next: boolean, shift: boolean) => {
    if (shift && lastClicked.current) {
      const a = pageThreadIds.indexOf(lastClicked.current)
      const b = pageThreadIds.indexOf(id)
      if (a !== -1 && b !== -1) {
        const range = pageThreadIds.slice(Math.min(a, b), Math.max(a, b) + 1)
        const set = new Set(selection)
        range.forEach((r) => (next ? set.add(r) : set.delete(r)))
        onSelectionChange([...set])
        lastClicked.current = id
        return
      }
    }
    const set = new Set(selection)
    if (next) set.add(id)
    else set.delete(id)
    lastClicked.current = id
    onSelectionChange([...set])
  }

  const rowHandlers: RowHandlers = { ...handlers, onSelect }

  const emptyView = VIEWS[route.view]
  const showTabs =
    settings.showCategoryTabs &&
    route.view === 'inbox' &&
    !route.search &&
    !route.labelId &&
    !narrow

  return (
    <div className="flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden rounded-none bg-surface sm:rounded-2xl">
      <ListToolbar
        route={route}
        navigate={navigate}
        selection={selection}
        onSelectionChange={onSelectionChange}
        pageThreadIds={pageThreadIds}
        allSelected={allSelected}
        someSelected={someSelected}
        onRefresh={onRefresh}
        refreshing={refreshing}
        total={total}
        start={start}
        pageSize={pageSize}
        page={page}
        onPageChange={onPageChange}
        narrow={narrow}
        listThreadIds={list.threads.map((t) => t.id)}
      />

      {showTabs && <CategoryTabs route={route} navigate={navigate} />}

      {selection.length > 0 && selection.length === pageThreadIds.length && total > pageSize && (
        <div className="bg-accent-soft px-4 py-2 text-center text-[13px] text-accent-ink">
          All {pluralize(selection.length, 'conversation')} on this page are selected.{' '}
          <button
            type="button"
            className="font-medium underline"
            onClick={() => onSelectionChange(list.threads.map((t) => t.id))}
          >
            Select all {total} conversations
          </button>
        </div>
      )}

      <div ref={listRef} className="min-h-0 flex-1 overflow-y-auto scrollbar-thin">
        {merged.length === 0 ? (
          <EmptyState
            title={
              route.search
                ? 'No messages matched your search'
                : route.labelId
                  ? 'No conversations with this label'
                  : emptyView.emptyTitle
            }
            subtitle={
              route.search
                ? 'Try different keywords, or remove some search operators.'
                : route.labelId
                  ? 'Apply this label to a conversation and it will show up here.'
                  : emptyView.emptySubtitle
            }
          />
        ) : (
          <ul>
            {merged.map((row, i) =>
              row.kind === 'thread' ? (
                <ThreadRow
                  key={row.item.id}
                  summary={row.item}
                  selected={selected.has(row.item.id)}
                  cursor={cursor === i}
                  view={route.view}
                  density={settings.density}
                  terms={terms}
                  now={now}
                  showPreview={settings.previewText && !narrow}
                  hoverActions={settings.hoverActions && !narrow}
                  handlers={rowHandlers}
                />
              ) : (
                <DraftRow
                  key={row.item.id}
                  draft={row.item}
                  cursor={cursor === i}
                  terms={terms}
                  now={now}
                  onOpen={() => onOpenDraft(row.item.id)}
                  onDiscard={() => actions.discardDraft(row.item.id)}
                />
              ),
            )}
          </ul>
        )}

        {merged.length > 0 && (
          <footer className="px-4 py-6 text-center text-[12px] text-ink-4">
            {route.view === 'trash'
              ? 'Messages that have been in Trash more than 30 days will be automatically deleted.'
              : route.view === 'spam'
                ? 'Messages that have been in Spam more than 30 days will be automatically deleted.'
                : `${data.account.name} · ${data.account.email}`}
          </footer>
        )}
      </div>
    </div>
  )
}

/* -------------------------------------------------------------------------- */
/*  Toolbar                                                                    */
/* -------------------------------------------------------------------------- */

interface ToolbarProps {
  route: Route
  selection: string[]
  onSelectionChange: (ids: string[]) => void
  pageThreadIds: string[]
  listThreadIds: string[]
  allSelected: boolean
  someSelected: boolean
  onRefresh: () => void
  refreshing: boolean
  total: number
  start: number
  pageSize: number
  page: number
  onPageChange: (p: number) => void
  narrow?: boolean
}

function ListToolbar({
  route,
  navigate,
  selection,
  onSelectionChange,
  pageThreadIds,
  listThreadIds,
  allSelected,
  someSelected,
  onRefresh,
  refreshing,
  total,
  start,
  pageSize,
  page,
  onPageChange,
  narrow,
}: ToolbarProps) {
  const { data } = useMail()
  const actions = useMailActions()
  const selectRef = useRef<HTMLButtonElement>(null)
  const moreRef = useRef<HTMLButtonElement>(null)
  const moveRef = useRef<HTMLButtonElement>(null)
  const labelRef = useRef<HTMLButtonElement>(null)
  const snoozeRef = useRef<HTMLButtonElement>(null)
  const [open, setOpen] = useState<'select' | 'more' | 'move' | 'label' | 'snooze' | null>(null)
  const close = () => setOpen(null)

  const inTrash = route.view === 'trash'
  const inSpam = route.view === 'spam'
  const anyUnread = selection.some((id) =>
    data.threads[id]?.messageIds.some((m) => data.messages[m] && !data.messages[m].read),
  )

  const clear = () => onSelectionChange([])
  const run = (fn: () => void) => {
    fn()
    clear()
  }

  const pickBy = (test: (id: string) => boolean) =>
    onSelectionChange(pageThreadIds.filter(test))

  const isUnread = (id: string) =>
    Boolean(data.threads[id]?.messageIds.some((m) => data.messages[m] && !data.messages[m].read))
  const isStarred = (id: string) =>
    Boolean(data.threads[id]?.messageIds.some((m) => data.messages[m]?.starred))

  const moreEntries: MenuEntry[] = someSelected
    ? [
        {
          id: 'unread',
          label: 'Mark as unread',
          icon: <Mail />,
          onSelect: () => run(() => actions.setRead(selection, false)),
        },
        {
          id: 'read',
          label: 'Mark as read',
          icon: <MailOpen />,
          onSelect: () => run(() => actions.setRead(selection, true)),
        },
        { type: 'separator', id: 's1' },
        {
          id: 'important',
          label: 'Mark as important',
          onSelect: () => run(() => actions.setImportant(selection, true)),
        },
        {
          id: 'notimportant',
          label: 'Mark as not important',
          onSelect: () => run(() => actions.setImportant(selection, false)),
        },
        {
          id: 'star',
          label: 'Add star',
          onSelect: () => run(() => actions.setStarred(selection, true)),
        },
        {
          id: 'unstar',
          label: 'Remove star',
          onSelect: () => run(() => actions.setStarred(selection, false)),
        },
        { type: 'separator', id: 's2' },
        {
          id: 'mute',
          label: 'Mute',
          icon: <VolumeX />,
          onSelect: () => run(() => actions.setMuted(selection, true)),
        },
        ...(inSpam
          ? [
              {
                id: 'notspam',
                label: 'Not spam',
                icon: <ShieldOff />,
                onSelect: () => run(() => actions.notSpam(selection)),
              } as MenuEntry,
            ]
          : []),
        ...(inTrash
          ? [
              {
                id: 'forever',
                label: 'Delete forever',
                icon: <Trash2 />,
                danger: true,
                onSelect: () => run(() => actions.deleteForever(selection)),
              } as MenuEntry,
            ]
          : []),
      ]
    : [
        {
          id: 'markall',
          label: 'Mark all as read',
          icon: <MailOpen />,
          disabled: !listThreadIds.length,
          onSelect: () => actions.setRead(listThreadIds, true),
        },
        {
          id: 'selectall',
          label: 'Select all conversations',
          disabled: !listThreadIds.length,
          onSelect: () => onSelectionChange(listThreadIds),
        },
        ...(inTrash || inSpam
          ? [
              { type: 'separator', id: 's3' } as MenuEntry,
              {
                id: 'empty',
                label: inTrash ? 'Empty Trash now' : 'Delete all spam now',
                icon: <Trash2 />,
                danger: true,
                disabled: !listThreadIds.length,
                onSelect: () =>
                  actions.emptyFolder(inTrash ? SYSTEM.trash : SYSTEM.spam, inTrash ? 'Trash' : 'Spam'),
              } as MenuEntry,
            ]
          : []),
      ]

  return (
    <div className="flex h-12 shrink-0 items-center gap-0.5 px-1 sm:px-2">
      <div className="flex items-center">
        <Checkbox
          checked={allSelected}
          indeterminate={someSelected && !allSelected}
          label="Select all conversations on this page"
          stopPropagation={false}
          onChange={(next) => onSelectionChange(next ? pageThreadIds : [])}
        />
        <button
          ref={selectRef}
          type="button"
          aria-label="Selection options"
          onClick={() => setOpen(open === 'select' ? null : 'select')}
          className="-ml-1.5 flex h-8 w-5 items-center justify-center rounded text-ink-3 hover:text-ink"
        >
          <ChevronDown className="h-4 w-4" />
        </button>
      </div>

      {someSelected ? (
        <div className="flex min-w-0 items-center gap-0.5">
          {inTrash ? (
            <IconButton label="Move to inbox" onClick={() => run(() => actions.untrash(selection))}>
              <ArchiveRestore />
            </IconButton>
          ) : (
            <IconButton
              label="Archive"
              shortcut="E"
              onClick={() => run(() => actions.archive(selection))}
            >
              <Archive />
            </IconButton>
          )}
          {!inSpam && (
            <IconButton label="Report spam" onClick={() => run(() => actions.markSpam(selection))}>
              <Ban />
            </IconButton>
          )}
          <IconButton
            label={inTrash ? 'Delete forever' : 'Delete'}
            shortcut="#"
            onClick={() => run(() => (inTrash ? actions.deleteForever(selection) : actions.trash(selection)))}
          >
            <Trash2 />
          </IconButton>
          <span className="mx-1 hidden h-5 w-px bg-line sm:block" />
          <IconButton
            label={anyUnread ? 'Mark as read' : 'Mark as unread'}
            className="hidden sm:inline-flex"
            onClick={() => run(() => actions.setRead(selection, anyUnread))}
          >
            {anyUnread ? <MailOpen /> : <Mail />}
          </IconButton>
          <IconButton
            ref={snoozeRef}
            label="Snooze"
            className="hidden sm:inline-flex"
            active={open === 'snooze'}
            onClick={() => setOpen(open === 'snooze' ? null : 'snooze')}
          >
            <Clock />
          </IconButton>
          <span className="mx-1 hidden h-5 w-px bg-line md:block" />
          <IconButton
            ref={moveRef}
            label="Move to"
            className="hidden md:inline-flex"
            active={open === 'move'}
            onClick={() => setOpen(open === 'move' ? null : 'move')}
          >
            <FolderInput />
          </IconButton>
          <IconButton
            ref={labelRef}
            label="Labels"
            className="hidden md:inline-flex"
            active={open === 'label'}
            onClick={() => setOpen(open === 'label' ? null : 'label')}
          >
            <Tag />
          </IconButton>
        </div>
      ) : (
        <IconButton label="Refresh" shortcut="R" onClick={onRefresh}>
          <RefreshCw className={refreshing ? 'animate-spin' : undefined} />
        </IconButton>
      )}

      <IconButton
        ref={moreRef}
        label="More"
        active={open === 'more'}
        onClick={() => setOpen(open === 'more' ? null : 'more')}
      >
        <EllipsisVertical />
      </IconButton>

      <div className="ml-auto flex items-center gap-0.5">
        {someSelected ? (
          <span className="px-2 text-[13px] text-ink-2">
            {pluralize(selection.length, 'selected')}
          </span>
        ) : (
          !narrow && (
            <span className="hidden px-2 text-[12px] tabular-nums text-ink-3 sm:block">
              {total === 0 ? '0' : `${start + 1}–${Math.min(total, start + pageSize)}`} of {total}
            </span>
          )
        )}
        <IconButton
          label="Newer"
          disabled={page === 0}
          onClick={() => onPageChange(page - 1)}
          size="sm"
        >
          <ChevronLeft />
        </IconButton>
        <IconButton
          label="Older"
          disabled={start + pageSize >= total}
          onClick={() => onPageChange(page + 1)}
          size="sm"
        >
          <ChevronRight />
        </IconButton>
      </div>

      <Menu
        anchorRef={selectRef}
        open={open === 'select'}
        onClose={close}
        ariaLabel="Select"
        entries={[
          { id: 'all', label: 'All', onSelect: () => onSelectionChange(pageThreadIds) },
          { id: 'none', label: 'None', onSelect: () => onSelectionChange([]) },
          { id: 'read', label: 'Read', onSelect: () => pickBy((id) => !isUnread(id)) },
          { id: 'unread', label: 'Unread', onSelect: () => pickBy(isUnread) },
          { id: 'starred', label: 'Starred', onSelect: () => pickBy(isStarred) },
          { id: 'unstarred', label: 'Unstarred', onSelect: () => pickBy((id) => !isStarred(id)) },
        ]}
      />
      <Menu
        anchorRef={moreRef}
        open={open === 'more'}
        onClose={close}
        ariaLabel="More actions"
        entries={moreEntries}
      />
      <Menu
        anchorRef={moveRef}
        open={open === 'move'}
        onClose={close}
        ariaLabel="Move to"
        entries={[
          { type: 'header', id: 'h', label: 'Move to' },
          {
            id: 'inbox',
            label: 'Inbox',
            icon: <Inbox />,
            onSelect: () => run(() => actions.moveToInbox(selection)),
          },
          {
            id: 'spam',
            label: 'Spam',
            icon: <Ban />,
            onSelect: () => run(() => actions.markSpam(selection)),
          },
          {
            id: 'trash',
            label: 'Trash',
            icon: <Trash2 />,
            onSelect: () => run(() => actions.trash(selection)),
          },
          { type: 'separator', id: 's' },
          {
            id: 'archive',
            label: 'Archive (remove from Inbox)',
            icon: <Archive />,
            onSelect: () => run(() => actions.archive(selection)),
          },
        ]}
      />
      <LabelMenu
        anchorRef={labelRef}
        open={open === 'label'}
        onClose={close}
        threadIds={selection}
      />
      <SnoozeMenu
        anchorRef={snoozeRef}
        open={open === 'snooze'}
        onClose={close}
        onPick={(iso, human) => run(() => actions.snooze(selection, iso, human))}
      />
    </div>
  )
}

/* -------------------------------------------------------------------------- */
/*  Category tabs                                                              */
/* -------------------------------------------------------------------------- */

function CategoryTabs({ route, navigate }: { route: Route; navigate: (r: Route) => void }) {
  const active = route.category ?? 'primary'
  return (
    <div className="flex shrink-0 overflow-x-auto no-scrollbar border-b border-line-soft">
      {CATEGORIES.map((c) => {
        const on = active === c.id
        const Icon = c.icon
        return (
          <button
            key={c.id}
            type="button"
            onClick={() => navigate({ view: 'inbox', category: c.id === 'primary' ? undefined : c.id })}
            className={cn(
              'relative flex min-w-[7rem] flex-1 items-center gap-3 px-4 py-3 text-[13px] font-medium transition-colors sm:min-w-[9rem]',
              on ? 'text-ink' : 'text-ink-3 hover:bg-surface-2 hover:text-ink-2',
            )}
          >
            <Icon className="h-5 w-5 shrink-0" style={{ color: on ? c.accent : undefined }} />
            <span className="truncate">{c.title}</span>
            {on && (
              <span
                className="absolute inset-x-0 bottom-0 h-[3px] rounded-t"
                style={{ backgroundColor: c.accent }}
              />
            )}
          </button>
        )
      })}
    </div>
  )
}

/* -------------------------------------------------------------------------- */
/*  Draft row & empty state                                                    */
/* -------------------------------------------------------------------------- */

function DraftRow({
  draft,
  cursor,
  terms,
  now,
  onOpen,
  onDiscard,
}: {
  draft: Draft
  cursor: boolean
  terms: string[]
  now: number
  onOpen: () => void
  onDiscard: () => void
}) {
  const { settings } = useSettings()
  const recipients = draft.to.map((a) => a.name || a.email).join(', ')
  const snippet = truncate(htmlToText(draft.bodyHtml), 200)

  return (
    <li
      className={cn(
        'group relative border-b border-line-soft/70 bg-read transition-colors hover:z-[1] hover:shadow-row',
        cursor && 'ring-1 ring-inset ring-accent/45',
      )}
    >
      <div
        role="button"
        tabIndex={-1}
        onClick={onOpen}
        className={cn(
          'flex cursor-pointer items-center gap-1 pl-2 pr-3 sm:pl-[6.25rem]',
          DENSITY_ROW[settings.density],
        )}
      >
        <span className="min-w-0 flex-1 truncate text-[14px]">
          <span className="mr-2 text-danger">Draft</span>
          <span className="text-ink">
            <Highlight text={draft.subject || '(no subject)'} terms={terms} />
          </span>
          <span className="text-ink-3">
            {recipients && ` — to ${recipients}`}
            {snippet && ` — ${snippet}`}
          </span>
        </span>
        <div className="relative flex w-[7rem] shrink-0 items-center justify-end self-stretch">
          <span className="text-[12px] text-ink-3 group-hover:invisible">
            {formatListDate(draft.updatedAt, new Date(now))}
          </span>
          <div
            className="absolute inset-y-0 right-0 hidden items-center group-hover:flex"
            onClick={(e) => e.stopPropagation()}
          >
            <IconButton label="Discard draft" size="sm" onClick={onDiscard}>
              <Trash2 />
            </IconButton>
          </div>
        </div>
      </div>
    </li>
  )
}

function EmptyState({ title, subtitle }: { title: string; subtitle: string }) {
  return (
    <div className="flex flex-col items-center justify-center gap-2 px-8 py-24 text-center">
      <div className="mb-2 flex h-16 w-16 items-center justify-center rounded-full bg-surface-2 text-ink-3">
        <Inbox className="h-7 w-7" />
      </div>
      <p className="text-[15px] font-medium text-ink">{title}</p>
      <p className="max-w-sm text-[13px] text-ink-3">{subtitle}</p>
    </div>
  )
}

import { useMemo, useRef, useState } from 'react'
import {
  Archive,
  ArchiveRestore,
  Ban,
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  Clock,
  EllipsisVertical,
  FolderInput,
  Inbox,
  Mail,
  MailOpen,
  RefreshCw,
  ShieldOff,
  Tag,
  Trash2,
  VolumeX,
} from 'lucide-react'
import { useMailActions } from '@/hooks/use-mail-actions'
import type { ListResult, ThreadSummary } from '@/lib/selectors'
import { SYSTEM, type Draft } from '@/lib/types'
import { cn, formatListDate, htmlToText, pluralize, truncate } from '@/lib/utils'
import { CATEGORIES, VIEWS } from '@/lib/views'
import { useMail } from '@/store/mail-store'
import type { Route } from '@/store/router'
import { DENSITY_ROW, useSettings } from '@/store/settings'
import { Checkbox, IconButton } from './ui/bits'
import { Menu, type MenuEntry } from './ui/popover'
import { Highlight } from './highlight'
import { LabelMenu } from './label-menu'
import { SnoozeMenu } from './snooze-menu'
import { ThreadRow, type RowHandlers } from './thread-row'

interface ListPaneProps {
  route: Route
  navigate: (r: Route) => void
  list: ListResult
  terms: string[]
  now: number
  selection: string[]
  onSelectionChange: (ids: string[]) => void
  cursor: number
  onCursorChange: (i: number) => void
  page: number
  onPageChange: (p: number) => void
  handlers: RowHandlers
  onOpenDraft: (id: string) => void
  onRefresh: () => void
  refreshing: boolean
  listRef: React.RefObject<HTMLDivElement | null>
  /** Narrow layout used beside the reading pane. */
  narrow?: boolean
}

export function ListPane({
  route,
  navigate,
  list,
  terms,
  now,
  selection,
  onSelectionChange,
  cursor,
  onCursorChange,
  page,
  onPageChange,
  handlers,
  onOpenDraft,
  onRefresh,
  refreshing,
  listRef,
  narrow,
}: ListPaneProps) {
  const { data } = useMail()
  const { settings } = useSettings()
  const actions = useMailActions()

  const pageSize = settings.pageSize
  const total = list.threads.length + list.drafts.length
  const start = page * pageSize

  const merged = useMemo(() => {
    const rows: ({ kind: 'thread'; item: ThreadSummary } | { kind: 'draft'; item: Draft })[] = [
      ...list.threads.map((t) => ({ kind: 'thread' as const, item: t })),
      ...list.drafts.map((d) => ({ kind: 'draft' as const, item: d })),
    ]
    if (list.drafts.length && list.threads.length) {
      rows.sort((a, b) => {
        const ad = a.kind === 'thread' ? a.item.date : a.item.updatedAt
        const bd = b.kind === 'thread' ? b.item.date : b.item.updatedAt
        return Date.parse(bd) - Date.parse(ad)
      })
    }
    return rows.slice(start, start + pageSize)
  }, [list.threads, list.drafts, start, pageSize])

  const pageThreadIds = merged.filter((r) => r.kind === 'thread').map((r) => r.item.id)
  const selected = new Set(selection)
  const allSelected = pageThreadIds.length > 0 && pageThreadIds.every((id) => selected.has(id))
  const someSelected = selection.length > 0

  const lastClicked = useRef<string | null>(null)

  const onSelect = (id: string, next: boolean, shift: boolean) => {
    if (shift && lastClicked.current) {
      const a = pageThreadIds.indexOf(lastClicked.current)
      const b = pageThreadIds.indexOf(id)
      if (a !== -1 && b !== -1) {
        const range = pageThreadIds.slice(Math.min(a, b), Math.max(a, b) + 1)
        const set = new Set(selection)
        range.forEach((r) => (next ? set.add(r) : set.delete(r)))
        onSelectionChange([...set])
        lastClicked.current = id
        return
      }
    }
    const set = new Set(selection)
    if (next) set.add(id)
    else set.delete(id)
    lastClicked.current = id
    onSelectionChange([...set])
  }

  const rowHandlers: RowHandlers = { ...handlers, onSelect }

  const emptyView = VIEWS[route.view]
  const showTabs =
    settings.showCategoryTabs &&
    route.view === 'inbox' &&
    !route.search &&
    !route.labelId &&
    !narrow

  return (
    <div className="flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden rounded-none bg-surface sm:rounded-2xl">
      <ListToolbar
        route={route}
        navigate={navigate}
        selection={selection}
        onSelectionChange={onSelectionChange}
        pageThreadIds={pageThreadIds}
        allSelected={allSelected}
        someSelected={someSelected}
        onRefresh={onRefresh}
        refreshing={refreshing}
        total={total}
        start={start}
        pageSize={pageSize}
        page={page}
        onPageChange={onPageChange}
        narrow={narrow}
        listThreadIds={list.threads.map((t) => t.id)}
      />

      {showTabs && <CategoryTabs route={route} navigate={navigate} />}

      {selection.length > 0 && selection.length === pageThreadIds.length && total > pageSize && (
        <div className="bg-accent-soft px-4 py-2 text-center text-[13px] text-accent-ink">
          All {pluralize(selection.length, 'conversation')} on this page are selected.{' '}
          <button
            type="button"
            className="font-medium underline"
            onClick={() => onSelectionChange(list.threads.map((t) => t.id))}
          >
            Select all {total} conversations
          </button>
        </div>
      )}

      <div ref={listRef} className="min-h-0 flex-1 overflow-y-auto scrollbar-thin">
        {merged.length === 0 ? (
          <EmptyState
            title={
              route.search
                ? 'No messages matched your search'
                : route.labelId
                  ? 'No conversations with this label'
                  : emptyView.emptyTitle
            }
            subtitle={
              route.search
                ? 'Try different keywords, or remove some search operators.'
                : route.labelId
                  ? 'Apply this label to a conversation and it will show up here.'
                  : emptyView.emptySubtitle
            }
          />
        ) : (
          <ul>
            {merged.map((row, i) =>
              row.kind === 'thread' ? (
                <ThreadRow
                  key={row.item.id}
                  summary={row.item}
                  selected={selected.has(row.item.id)}
                  cursor={cursor === i}
                  view={route.view}
                  density={settings.density}
                  terms={terms}
                  now={now}
                  showPreview={settings.previewText && !narrow}
                  hoverActions={settings.hoverActions && !narrow}
                  handlers={rowHandlers}
                />
              ) : (
                <DraftRow
                  key={row.item.id}
                  draft={row.item}
                  cursor={cursor === i}
                  terms={terms}
                  now={now}
                  onOpen={() => onOpenDraft(row.item.id)}
                  onDiscard={() => actions.discardDraft(row.item.id)}
                />
              ),
            )}
          </ul>
        )}

        {merged.length > 0 && (
          <footer className="px-4 py-6 text-center text-[12px] text-ink-4">
            {route.view === 'trash'
              ? 'Messages that have been in Trash more than 30 days will be automatically deleted.'
              : route.view === 'spam'
                ? 'Messages that have been in Spam more than 30 days will be automatically deleted.'
                : `${data.account.name} · ${data.account.email}`}
          </footer>
        )}
      </div>
    </div>
  )
}

/* -------------------------------------------------------------------------- */
/*  Toolbar                                                                    */
/* -------------------------------------------------------------------------- */

interface ToolbarProps {
  route: Route
  selection: string[]
  onSelectionChange: (ids: string[]) => void
  pageThreadIds: string[]
  listThreadIds: string[]
  allSelected: boolean
  someSelected: boolean
  onRefresh: () => void
  refreshing: boolean
  total: number
  start: number
  pageSize: number
  page: number
  onPageChange: (p: number) => void
  narrow?: boolean
}

function ListToolbar({
  route,
  selection,
  onSelectionChange,
  pageThreadIds,
  listThreadIds,
  allSelected,
  someSelected,
  onRefresh,
  refreshing,
  total,
  start,
  pageSize,
  page,
  onPageChange,
  narrow,
}: ToolbarProps) {
  const { data } = useMail()
  const actions = useMailActions()
  const selectRef = useRef<HTMLButtonElement>(null)
  const moreRef = useRef<HTMLButtonElement>(null)
  const moveRef = useRef<HTMLButtonElement>(null)
  const labelRef = useRef<HTMLButtonElement>(null)
  const snoozeRef = useRef<HTMLButtonElement>(null)
  const [open, setOpen] = useState<'select' | 'more' | 'move' | 'label' | 'snooze' | null>(null)
  const close = () => setOpen(null)

  const inTrash = route.view === 'trash'
  const inSpam = route.view === 'spam'
  const anyUnread = selection.some((id) =>
    data.threads[id]?.messageIds.some((m) => data.messages[m] && !data.messages[m].read),
  )

  const clear = () => onSelectionChange([])
  const run = (fn: () => void) => {
    fn()
    clear()
  }

  const pickBy = (test: (id: string) => boolean) =>
    onSelectionChange(pageThreadIds.filter(test))

  const isUnread = (id: string) =>
    Boolean(data.threads[id]?.messageIds.some((m) => data.messages[m] && !data.messages[m].read))
  const isStarred = (id: string) =>
    Boolean(data.threads[id]?.messageIds.some((m) => data.messages[m]?.starred))

  const moreEntries: MenuEntry[] = someSelected
    ? [
        {
          id: 'unread',
          label: 'Mark as unread',
          icon: <Mail />,
          onSelect: () => run(() => actions.setRead(selection, false)),
        },
        {
          id: 'read',
          label: 'Mark as read',
          icon: <MailOpen />,
          onSelect: () => run(() => actions.setRead(selection, true)),
        },
        { type: 'separator', id: 's1' },
        {
          id: 'important',
          label: 'Mark as important',
          onSelect: () => run(() => actions.setImportant(selection, true)),
        },
        {
          id: 'notimportant',
          label: 'Mark as not important',
          onSelect: () => run(() => actions.setImportant(selection, false)),
        },
        {
          id: 'star',
          label: 'Add star',
          onSelect: () => run(() => actions.setStarred(selection, true)),
        },
        {
          id: 'unstar',
          label: 'Remove star',
          onSelect: () => run(() => actions.setStarred(selection, false)),
        },
        { type: 'separator', id: 's2' },
        {
          id: 'mute',
          label: 'Mute',
          icon: <VolumeX />,
          onSelect: () => run(() => actions.setMuted(selection, true)),
        },
        ...(inSpam
          ? [
              {
                id: 'notspam',
                label: 'Not spam',
                icon: <ShieldOff />,
                onSelect: () => run(() => actions.notSpam(selection)),
              } as MenuEntry,
            ]
          : []),
        ...(inTrash
          ? [
              {
                id: 'forever',
                label: 'Delete forever',
                icon: <Trash2 />,
                danger: true,
                onSelect: () => run(() => actions.deleteForever(selection)),
              } as MenuEntry,
            ]
          : []),
      ]
    : [
        {
          id: 'markall',
          label: 'Mark all as read',
          icon: <MailOpen />,
          disabled: !listThreadIds.length,
          onSelect: () => actions.setRead(listThreadIds, true),
        },
        {
          id: 'selectall',
          label: 'Select all conversations',
          disabled: !listThreadIds.length,
          onSelect: () => onSelectionChange(listThreadIds),
        },
        ...(inTrash || inSpam
          ? [
              { type: 'separator', id: 's3' } as MenuEntry,
              {
                id: 'empty',
                label: inTrash ? 'Empty Trash now' : 'Delete all spam now',
                icon: <Trash2 />,
                danger: true,
                disabled: !listThreadIds.length,
                onSelect: () =>
                  actions.emptyFolder(inTrash ? SYSTEM.trash : SYSTEM.spam, inTrash ? 'Trash' : 'Spam'),
              } as MenuEntry,
            ]
          : []),
      ]

  return (
    <div className="flex h-12 shrink-0 items-center gap-0.5 px-1 sm:px-2">
      <div className="flex items-center">
        <Checkbox
          checked={allSelected}
          indeterminate={someSelected && !allSelected}
          label="Select all conversations on this page"
          stopPropagation={false}
          onChange={(next) => onSelectionChange(next ? pageThreadIds : [])}
        />
        <button
          ref={selectRef}
          type="button"
          aria-label="Selection options"
          onClick={() => setOpen(open === 'select' ? null : 'select')}
          className="-ml-1.5 flex h-8 w-5 items-center justify-center rounded text-ink-3 hover:text-ink"
        >
          <ChevronDown className="h-4 w-4" />
        </button>
      </div>

      {someSelected ? (
        <div className="flex min-w-0 items-center gap-0.5">
          {inTrash ? (
            <IconButton label="Move to inbox" onClick={() => run(() => actions.untrash(selection))}>
              <ArchiveRestore />
            </IconButton>
          ) : (
            <IconButton
              label="Archive"
              shortcut="E"
              onClick={() => run(() => actions.archive(selection))}
            >
              <Archive />
            </IconButton>
          )}
          {!inSpam && (
            <IconButton label="Report spam" onClick={() => run(() => actions.markSpam(selection))}>
              <Ban />
            </IconButton>
          )}
          <IconButton
            label={inTrash ? 'Delete forever' : 'Delete'}
            shortcut="#"
            onClick={() => run(() => (inTrash ? actions.deleteForever(selection) : actions.trash(selection)))}
          >
            <Trash2 />
          </IconButton>
          <span className="mx-1 hidden h-5 w-px bg-line sm:block" />
          <IconButton
            label={anyUnread ? 'Mark as read' : 'Mark as unread'}
            className="hidden sm:inline-flex"
            onClick={() => run(() => actions.setRead(selection, anyUnread))}
          >
            {anyUnread ? <MailOpen /> : <Mail />}
          </IconButton>
          <IconButton
            ref={snoozeRef}
            label="Snooze"
            className="hidden sm:inline-flex"
            active={open === 'snooze'}
            onClick={() => setOpen(open === 'snooze' ? null : 'snooze')}
          >
            <Clock />
          </IconButton>
          <span className="mx-1 hidden h-5 w-px bg-line md:block" />
          <IconButton
            ref={moveRef}
            label="Move to"
            className="hidden md:inline-flex"
            active={open === 'move'}
            onClick={() => setOpen(open === 'move' ? null : 'move')}
          >
            <FolderInput />
          </IconButton>
          <IconButton
            ref={labelRef}
            label="Labels"
            className="hidden md:inline-flex"
            active={open === 'label'}
            onClick={() => setOpen(open === 'label' ? null : 'label')}
          >
            <Tag />
          </IconButton>
        </div>
      ) : (
        <IconButton label="Refresh" shortcut="R" onClick={onRefresh}>
          <RefreshCw className={refreshing ? 'animate-spin' : undefined} />
        </IconButton>
      )}

      <IconButton
        ref={moreRef}
        label="More"
        active={open === 'more'}
        onClick={() => setOpen(open === 'more' ? null : 'more')}
      >
        <EllipsisVertical />
      </IconButton>

      <div className="ml-auto flex items-center gap-0.5">
        {someSelected ? (
          <span className="px-2 text-[13px] text-ink-2">
            {pluralize(selection.length, 'selected')}
          </span>
        ) : (
          !narrow && (
            <span className="hidden px-2 text-[12px] tabular-nums text-ink-3 sm:block">
              {total === 0 ? '0' : `${start + 1}–${Math.min(total, start + pageSize)}`} of {total}
            </span>
          )
        )}
        <IconButton
          label="Newer"
          disabled={page === 0}
          onClick={() => onPageChange(page - 1)}
          size="sm"
        >
          <ChevronLeft />
        </IconButton>
        <IconButton
          label="Older"
          disabled={start + pageSize >= total}
          onClick={() => onPageChange(page + 1)}
          size="sm"
        >
          <ChevronRight />
        </IconButton>
      </div>

      <Menu
        anchorRef={selectRef}
        open={open === 'select'}
        onClose={close}
        ariaLabel="Select"
        entries={[
          { id: 'all', label: 'All', onSelect: () => onSelectionChange(pageThreadIds) },
          { id: 'none', label: 'None', onSelect: () => onSelectionChange([]) },
          { id: 'read', label: 'Read', onSelect: () => pickBy((id) => !isUnread(id)) },
          { id: 'unread', label: 'Unread', onSelect: () => pickBy(isUnread) },
          { id: 'starred', label: 'Starred', onSelect: () => pickBy(isStarred) },
          { id: 'unstarred', label: 'Unstarred', onSelect: () => pickBy((id) => !isStarred(id)) },
        ]}
      />
      <Menu
        anchorRef={moreRef}
        open={open === 'more'}
        onClose={close}
        ariaLabel="More actions"
        entries={moreEntries}
      />
      <Menu
        anchorRef={moveRef}
        open={open === 'move'}
        onClose={close}
        ariaLabel="Move to"
        entries={[
          { type: 'header', id: 'h', label: 'Move to' },
          {
            id: 'inbox',
            label: 'Inbox',
            icon: <Inbox />,
            onSelect: () => run(() => actions.moveToInbox(selection)),
          },
          {
            id: 'spam',
            label: 'Spam',
            icon: <Ban />,
            onSelect: () => run(() => actions.markSpam(selection)),
          },
          {
            id: 'trash',
            label: 'Trash',
            icon: <Trash2 />,
            onSelect: () => run(() => actions.trash(selection)),
          },
          { type: 'separator', id: 's' },
          {
            id: 'archive',
            label: 'Archive (remove from Inbox)',
            icon: <Archive />,
            onSelect: () => run(() => actions.archive(selection)),
          },
        ]}
      />
      <LabelMenu
        anchorRef={labelRef}
        open={open === 'label'}
        onClose={close}
        threadIds={selection}
      />
      <SnoozeMenu
        anchorRef={snoozeRef}
        open={open === 'snooze'}
        onClose={close}
        onPick={(iso, human) => run(() => actions.snooze(selection, iso, human))}
      />
    </div>
  )
}

/* -------------------------------------------------------------------------- */
/*  Category tabs                                                              */
/* -------------------------------------------------------------------------- */

function CategoryTabs({ route, navigate }: { route: Route; navigate: (r: Route) => void }) {
  const active = route.category ?? 'primary'
  return (
    <div className="flex shrink-0 overflow-x-auto no-scrollbar border-b border-line-soft">
      {CATEGORIES.map((c) => {
        const on = active === c.id
        const Icon = c.icon
        return (
          <button
            key={c.id}
            type="button"
            onClick={() => navigate({ view: 'inbox', category: c.id === 'primary' ? undefined : c.id })}
            className={cn(
              'relative flex min-w-[7rem] flex-1 items-center gap-3 px-4 py-3 text-[13px] font-medium transition-colors sm:min-w-[9rem]',
              on ? 'text-ink' : 'text-ink-3 hover:bg-surface-2 hover:text-ink-2',
            )}
          >
            <Icon className="h-5 w-5 shrink-0" style={{ color: on ? c.accent : undefined }} />
            <span className="truncate">{c.title}</span>
            {on && (
              <span
                className="absolute inset-x-0 bottom-0 h-[3px] rounded-t"
                style={{ backgroundColor: c.accent }}
              />
            )}
          </button>
        )
      })}
    </div>
  )
}

/* -------------------------------------------------------------------------- */
/*  Draft row & empty state                                                    */
/* -------------------------------------------------------------------------- */

function DraftRow({
  draft,
  cursor,
  terms,
  now,
  onOpen,
  onDiscard,
}: {
  draft: Draft
  cursor: boolean
  terms: string[]
  now: number
  onOpen: () => void
  onDiscard: () => void
}) {
  const { settings } = useSettings()
  const recipients = draft.to.map((a) => a.name || a.email).join(', ')
  const snippet = truncate(htmlToText(draft.bodyHtml), 200)

  return (
    <li
      className={cn(
        'group relative border-b border-line-soft/70 bg-read transition-colors hover:z-[1] hover:shadow-row',
        cursor && 'ring-1 ring-inset ring-accent/45',
      )}
    >
      <div
        role="button"
        tabIndex={-1}
        onClick={onOpen}
        className={cn(
          'flex cursor-pointer items-center gap-1 pl-2 pr-3 sm:pl-[6.25rem]',
          DENSITY_ROW[settings.density],
        )}
      >
        <span className="min-w-0 flex-1 truncate text-[14px]">
          <span className="mr-2 text-danger">Draft</span>
          <span className="text-ink">
            <Highlight text={draft.subject || '(no subject)'} terms={terms} />
          </span>
          <span className="text-ink-3">
            {recipients && ` — to ${recipients}`}
            {snippet && ` — ${snippet}`}
          </span>
        </span>
        <div className="relative flex w-[7rem] shrink-0 items-center justify-end self-stretch">
          <span className="text-[12px] text-ink-3 group-hover:invisible">
            {formatListDate(draft.updatedAt, new Date(now))}
          </span>
          <div
            className="absolute inset-y-0 right-0 hidden items-center group-hover:flex"
            onClick={(e) => e.stopPropagation()}
          >
            <IconButton label="Discard draft" size="sm" onClick={onDiscard}>
              <Trash2 />
            </IconButton>
          </div>
        </div>
      </div>
    </li>
  )
}

function EmptyState({ title, subtitle }: { title: string; subtitle: string }) {
  return (
    <div className="flex flex-col items-center justify-center gap-2 px-8 py-24 text-center">
      <div className="mb-2 flex h-16 w-16 items-center justify-center rounded-full bg-surface-2 text-ink-3">
        <Inbox className="h-7 w-7" />
      </div>
      <p className="text-[15px] font-medium text-ink">{title}</p>
      <p className="max-w-sm text-[13px] text-ink-3">{subtitle}</p>
    </div>
  )
}

input.content:
import { useRef, useState } from 'react'
import {
  ChevronDown,
  CornerUpLeft,
  CornerUpRight,
  EllipsisVertical,
  Printer,
  Star,
  Trash2,
} from 'lucide-react'
import { useMailActions } from '@/hooks/use-mail-actions'
import type { Message } from '@/lib/types'
import {
  cn,
  displayName,
  formatFullDate,
  formatMessageDate,
  formatRelative,
  htmlToText,
  truncate,
} from '@/lib/utils'
import { useMail } from '@/store/mail-store'
import { Avatar, IconButton } from './ui/bits'
import { Menu, Popover } from './ui/popover'
import { AttachmentCard } from './attachments'

interface MessageItemProps {
  message: Message
  expanded: boolean
  onToggle: () => void
  onReply: (mode: 'reply' | 'replyAll' | 'forward') => void
  now: number
  /** Last message in the thread gets the reply buttons below it. */
  isLast: boolean
}

export function MessageItem({
  message: m,
  expanded,
  onToggle,
  onReply,
  now,
  isLast,
}: MessageItemProps) {
  const { data } = useMail()
  const actions = useMailActions()
  const me = data.account.email
  const detailsRef = useRef<HTMLButtonElement>(null)
  const moreRef = useRef<HTMLButtonElement>(null)
  const [details, setDetails] = useState(false)
  const [more, setMore] = useState(false)
  const [showQuoted, setShowQuoted] = useState(false)

  const recipients = [...m.to, ...m.cc]
  const toLine = recipients.length
    ? `to ${recipients.map((a) => displayName(a, me)).join(', ')}`
    : 'to (no recipients)'

  if (!expanded) {
    return (
      <article
        className={cn(
          'group flex cursor-pointer items-center gap-3 border-b border-line-soft px-3 py-3 transition-colors hover:bg-surface-2 sm:px-6',
          !m.read && 'font-medium',
        )}
        onClick={onToggle}
      >
        <Avatar name={m.from.name} email={m.from.email} size={32} className="hidden sm:inline-flex" />
        <span className="w-[8rem] shrink-0 truncate text-[14px] text-ink sm:w-[10rem]">
          {displayName(m.from, me)}
        </span>
        <span className="min-w-0 flex-1 truncate text-[13px] font-normal text-ink-3">
          {truncate(htmlToText(m.bodyHtml), 160)}
        </span>
        {m.attachments.length > 0 && (
          <span className="hidden shrink-0 text-[12px] text-ink-4 sm:block">
            {m.attachments.length} file{m.attachments.length > 1 ? 's' : ''}
          </span>
        )}
        <span className="shrink-0 text-[12px] font-normal text-ink-3">
          {formatMessageDate(m.date, new Date(now))}
        </span>
      </article>
    )
  }

  return (
    <article className="border-b border-line-soft px-3 pb-5 pt-4 last:border-b-0 sm:px-6">
      <header className="flex items-start gap-3">
        <Avatar name={m.from.name} email={m.from.email} size={40} className="mt-0.5" />
        <div className="min-w-0 flex-1">
          <div className="flex flex-wrap items-baseline gap-x-2">
            <button
              type="button"
              onClick={onToggle}
              className="truncate text-[14px] font-semibold text-ink"
            >
              {m.outgoing ? 'me' : m.from.name || m.from.email}
            </button>
            <span className="truncate text-[12px] text-ink-3">
              &lt;{m.from.email}&gt;
            </span>
          </div>
          <button
            ref={detailsRef}
            type="button"
            onClick={() => setDetails((v) => !v)}
            className="mt-0.5 flex items-center gap-1 text-[12px] text-ink-3 hover:text-ink"
          >
            <span className="max-w-[60vw] truncate">{toLine}</span>
            <ChevronDown className="h-3.5 w-3.5" />
          </button>
        </div>
        <div className="flex shrink-0 items-center gap-0.5">
          <span
            className="hidden text-[12px] text-ink-3 sm:block"
            title={formatFullDate(m.date)}
          >
            {formatMessageDate(m.date, new Date(now))}{' '}
            <span className="text-ink-4">({formatRelative(m.date, new Date(now))})</span>
          </span>
          <IconButton
            label={m.starred ? 'Remove star' : 'Add star'}
            size="sm"
            onClick={() => actions.toggleMessageStar(m.id)}
          >
            <Star className={cn(m.starred && 'fill-star text-star')} />
          </IconButton>
          <IconButton label="Reply" size="sm" onClick={() => onReply('reply')}>
            <CornerUpLeft />
          </IconButton>
          <IconButton
            ref={moreRef}
            label="More"
            size="sm"
            active={more}
            onClick={() => setMore((v) => !v)}
          >
            <EllipsisVertical />
          </IconButton>
        </div>
      </header>

      <div className="mt-3 sm:pl-[52px]">
        <MessageBody html={m.bodyHtml} showQuoted={showQuoted} onShowQuoted={() => setShowQuoted(true)} />

        {m.attachments.length > 0 && (
          <div className="mt-5 border-t border-line-soft pt-4">
            <p className="mb-2 text-[12px] text-ink-3">
              {m.attachments.length} attachment{m.attachments.length > 1 ? 's' : ''}
            </p>
            <div className="flex flex-wrap gap-3">
              {m.attachments.map((a) => (
                <AttachmentCard key={a.id} attachment={a} />
              ))}
            </div>
          </div>
        )}

        {isLast && (
          <div className="mt-5 flex flex-wrap gap-2">
            <ReplyButton icon={<CornerUpLeft />} label="Reply" onClick={() => onReply('reply')} />
            {recipients.length > 1 && (
              <ReplyButton
                icon={<CornerUpLeft />}
                label="Reply all"
                onClick={() => onReply('replyAll')}
              />
            )}
            <ReplyButton
              icon={<CornerUpRight />}
              label="Forward"
              onClick={() => onReply('forward')}
            />
          </div>
        )}
      </div>

      <Popover
        anchorRef={detailsRef}
        open={details}
        onClose={() => setDetails(false)}
        role="dialog"
        ariaLabel="Message details"
        className="max-w-[min(28rem,92vw)] px-4 py-3"
      >
        <dl className="grid grid-cols-[auto_1fr] gap-x-3 gap-y-1 text-[12px]">
          <dt className="text-right text-ink-3">from:</dt>
          <dd className="text-ink">
            {m.from.name} &lt;{m.from.email}&gt;
          </dd>
          <dt className="text-right text-ink-3">to:</dt>
          <dd className="text-ink">{m.to.map((a) => a.email).join(', ') || '—'}</dd>
          {m.cc.length > 0 && (
            <>
              <dt className="text-right text-ink-3">cc:</dt>
              <dd className="text-ink">{m.cc.map((a) => a.email).join(', ')}</dd>
            </>
          )}
          {m.bcc.length > 0 && (
            <>
              <dt className="text-right text-ink-3">bcc:</dt>
              <dd className="text-ink">{m.bcc.map((a) => a.email).join(', ')}</dd>
            </>
          )}
          <dt className="text-right text-ink-3">date:</dt>
          <dd className="text-ink">{formatFullDate(m.date)}</dd>
          <dt className="text-right text-ink-3">mailed-by:</dt>
          <dd className="text-ink">{m.from.email.split('@')[1]}</dd>
        </dl>
      </Popover>

      <Menu
        anchorRef={moreRef}
        open={more}
        onClose={() => setMore(false)}
        align="end"
        ariaLabel="Message actions"
        entries={[
          { id: 'reply', label: 'Reply', icon: <CornerUpLeft />, onSelect: () => onReply('reply') },
          {
            id: 'replyall',
            label: 'Reply all',
            icon: <CornerUpLeft />,
            onSelect: () => onReply('replyAll'),
          },
          {
            id: 'forward',
            label: 'Forward',
            icon: <CornerUpRight />,
            onSelect: () => onReply('forward'),
          },
          { type: 'separator', id: 's1' },
          {
            id: 'unread',
            label: 'Mark unread from here',
            onSelect: () => actions.markMessageRead(m.id, false),
          },
          {
            id: 'star',
            label: m.starred ? 'Remove star' : 'Add star',
            onSelect: () => actions.toggleMessageStar(m.id),
          },
          { type: 'separator', id: 's2' },
          { id: 'print', label: 'Print', icon: <Printer />, onSelect: () => window.print() },
          {
            id: 'delete',
            label: 'Delete this message',
            icon: <Trash2 />,
            danger: true,
            onSelect: () => actions.trash([m.threadId]),
          },
        ]}
      />
    </article>
  )
}

function ReplyButton({
  icon,
  label,
  onClick,
}: {
  icon: React.ReactNode
  label: string
  onClick: () => void
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className="inline-flex h-9 items-center gap-2 rounded-full border border-line px-4 text-[13px] font-medium text-ink-2 transition-colors hover:bg-surface-2 hover:text-ink [&_svg]:h-[18px] [&_svg]:w-[18px]"
    >
      {icon}
      {label}
    </button>
  )
}

function MessageBody({
  html,
  showQuoted,
  onShowQuoted,
}: {
  html: string
  showQuoted: boolean
  onShowQuoted: () => void
}) {
  const hasQuote = html.includes('class="quoted"')
  const visible = hasQuote && !showQuoted ? html.replace(/<div class="quoted">[\s\S]*$/, '') : html

  return (
    <div>
      <div className="mail-body text-[14px] leading-[1.6] text-ink" dangerouslySetInnerHTML={{ __html: visible }} />
      {hasQuote && !showQuoted && (
        <button
          type="button"
          onClick={onShowQuoted}
          aria-label="Show trimmed content"
          className="mt-2 inline-flex h-5 items-center rounded bg-surface-3 px-2 text-[13px] font-bold leading-none text-ink-3 hover:bg-line"
        >
          ···
        </button>
      )}
    </div>
  )
}

