            title={a.email}
            className={cn(
              'inline-flex max-w-full items-center gap-1 rounded-full py-0.5 pl-0.5 pr-1 text-[13px]',
              isEmail(a.email) ? 'bg-surface-3 text-ink' : 'bg-danger/12 text-danger',
            )}
          >
            <Avatar name={a.name} email={a.email} size={20} />
            <span className="truncate">{a.name || a.email}</span>
            <button
              type="button"
              aria-label={`Remove ${a.email}`}
              onClick={(e) => {
                e.stopPropagation()
                onChange(value.filter((_, idx) => idx !== i))
              }}
              className="rounded-full p-0.5 text-ink-3 hover:bg-line hover:text-ink"
            >
              <X className="h-3 w-3" />
            </button>
          </span>
        ))}
        <input
          ref={inputRef}
          value={text}
          autoFocus={autoFocus}
          aria-label={label}
          onChange={(e) => {
            setText(e.target.value)
            setHighlight(0)
          }}
          onFocus={() => setFocused(true)}
          onBlur={() => {
            window.setTimeout(() => setFocused(false), 120)
            commitText()
          }}
          onPaste={(e) => {
            const pasted = e.clipboardData.getData('text')
            if (/[,;\n]/.test(pasted)) {
              e.preventDefault()
              for (const part of pasted.split(/[,;\n]/)) add(parseAddress(part))
            }
          }}
