            } else if (e.key === 'ArrowUp' && suggestions.length) {
              e.preventDefault()
              setHighlight((h) => (h - 1 + suggestions.length) % suggestions.length)
            } else if (e.key === 'Enter' || e.key === 'Tab' || e.key === ',' || e.key === ';') {
              if (suggestions.length && text.trim() && e.key !== 'Tab') {
