        reader.onload = () => {
          compose.update(draft.id, {
            attachments: [
              ...(compose.windows.find((w) => w.draft.id === draft.id)?.draft.attachments ?? []),
            ].map((a) => (a.id === att.id ? { ...a, previewImage: String(reader.result) } : a)),
          })
        }
