          onClick={() => setShowFormat((v) => !v)}
        >
          <Pen />
        </IconButton>
        <IconButton label="Attach files" size="sm" onClick={() => fileRef.current?.click()}>
          <Paperclip />
        </IconButton>
        <input
          ref={fileRef}
