          <IconButton label="Discard draft" size="sm" onClick={() => compose.discard(draft.id)}>
            <Trash2 />
          </IconButton>
        </span>
      </footer>

      <SnoozeMenu
        anchorRef={scheduleRef}
        open={menu === 'schedule'}
        onClose={() => setMenu(null)}
        align="start"
