        onChange={(bodyHtml) => set({ bodyHtml })}
      />

      {draft.attachments.length > 0 && (
        <div className="flex shrink-0 flex-wrap gap-2 border-t border-line-soft px-4 py-2">
          {draft.attachments.map((a) => (
            <span
