        >
          <Pen />
        </IconButton>
        <IconButton label="Attach files" size="sm" onClick={() => fileRef.current?.click()}>
          <Paperclip />
        </IconButton>
        <input
          ref={fileRef}
          type="file"
          multiple
          className="hidden"
          onChange={(e) => {
            attach(e.target.files)
            e.target.value = ''
          }}
        />
        <IconButton
          ref={moreRef}
