      <SnoozeMenu
        anchorRef={scheduleRef}
        open={menu === 'schedule'}
        onClose={() => setMenu(null)}
        align="start"
        title="Schedule send"
        verb="Schedule send"
        onPick={(iso) => onSend(draft, iso)}
      />
      <Menu
        anchorRef={moreRef}
        open={menu === 'more'}
