          {
            id: 'sig',
            label: 'Insert signature',
            disabled: !settings.signature.trim(),
            onSelect: () =>
              set({
                bodyHtml: `${draft.bodyHtml}<p><br></p><p class="sig" style="color:#80868b">--<br>${settings.signature
                  .split('\n')
                  .join('<br>')}</p>`,
