      ['!', 'Report spam'],
      ['b', 'Snooze'],
      ['l', 'Label as…'],
      ['r', 'Reply'],
      ['a', 'Reply all'],
      ['f', 'Forward'],
      ['Shift + i', 'Mark as read'],
      ['Shift + u', 'Mark as unread'],
      ['z', 'Undo the last action'],
    ],
  },
  {
    title: 'Application',
