      </header>

      <div className="min-h-0 flex-1 overflow-y-auto scrollbar-thin px-5 py-4">
        {tab === 'general' && <GeneralTab />}
        {tab === 'inbox' && <InboxTab />}
        {tab === 'labels' && <LabelsTab />}
        {tab === 'advanced' && <AdvancedTab navigate={navigate} />}
