      </div>

      <div className="min-h-0 flex-1 overflow-y-auto scrollbar-thin pr-1">
        <ul className="space-y-0.5">
          {SIDEBAR_PRIMARY.map((id) => (
            <NavItem
              key={id}
              id={id}
              active={isActiveView(id)}
              collapsed={collapsed}
              count={countFor(id)}

